INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$eb775f90$SATQ$, $SATQ$8ede9e22-1466-42a3-b2ec-3c9983b93ef3$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Annual Car Production in the United States, 1910&ndash;1925</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Year</th><th scope="col" style="text-align: center; vertical-align: bottom;">Number of cars produced</th><th scope="col" style="text-align: center; vertical-align: bottom;">Number of companies producing cars</th></tr></thead><tbody><tr><th scope="row" style="text-align: center;">1910</th><td style="text-align: center;">123,990</td><td style="text-align: center;">320</td></tr><tr><th scope="row" style="text-align: center;">1915</th><td style="text-align: center;">548,139</td><td style="text-align: center;">224</td></tr><tr><th scope="row" style="text-align: center;">1920</th><td style="text-align: center;">1,651,625</td><td style="text-align: center;">197</td></tr><tr><th scope="row" style="text-align: center;">1925</th><td style="text-align: center;">3,185,881</td><td style="text-align: center;">80</td></tr></tbody></table></figure></p>
<p>A student is using the table as part of a social studies class presentation on the US auto industry in the early twentieth century. The student notes that, according to the table, from 1910 to 1925 <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the statement?</p>$SATQ$, $SATQ$[{"id":"abcf72f0-d6ac-4d1e-bad3-d98d72a797ec","content":"<p>the number of cars produced increased but the number of companies producing cars decreased.</p>"},{"id":"77bece04-c7d6-4b87-8373-ade3b0e11d26","content":"<p>both the number of cars produced and the number of companies producing cars remained unchanged.</p>"},{"id":"498cfa2c-a267-472e-9bfb-5a2c5f3c4ad9","content":"<p>the number of cars produced decreased but the number of companies producing cars remained unchanged.</p>"},{"id":"27dfaf0a-bbbe-4d33-bfc9-dc38fe3dc1e2","content":"<p>both the number of cars produced and the number of companies producing cars increased.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["abcf72f0-d6ac-4d1e-bad3-d98d72a797ec"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most effectively uses data from the table to complete the statement about the US auto industry in the early twentieth century. The table shows the number of cars produced annually and number of companies producing cars in the United States between 1910 and 1925 in increments of five years. According to the table, the number of cars produced consistently increased from one increment to the next, going from 123,990 cars in 1910 to 3,185,881 cars in 1925. At the same time, the table shows that the number of companies producing cars consistently decreased, going from 320 companies in 1910 to only 80 companies in 1925. Thus, the table shows that the number of cars produced increased from 1910 to 1925, even as the number of companies producing cars decreased.</p><p>Choice B is incorrect. The table shows that the number of cars produced in the US increased, going from 123,990 in 1910 to 3,185,881 in 1925, instead of remaining unchanged, and the table also shows that the number of companies producing cars decreased from 320 to 80 instead of remaining unchanged. Choice C is incorrect because the table indicates that the number of cars produced consistently increased from 1910 to 1925, going from 123,990 cars to 3,185,881 cars, instead of decreasing; moreover, the table shows that the number of companies producing cars from 1910 to 1925 declined from 320 to 80 instead of remaining unchanged. Choice D is incorrect because the table indicates that the number of companies producing cars consistently decreased from 1910 to 1925, going from 320 companies to only 80 companies.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"eb775f90","external_id":"8ede9e22-1466-42a3-b2ec-3c9983b93ef3","vaultid":null,"uId":"7a5e56a1-8281-43b3-8829-618f1e0bf39d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Annual Car Production in the United States, 1910&ndash;1925</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Year</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Number of cars produced</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Number of companies producing cars</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: center;\">1910</th><td style=\"text-align: center;\">123,990</td><td style=\"text-align: center;\">320</td></tr><tr><th scope=\"row\" style=\"text-align: center;\">1915</th><td style=\"text-align: center;\">548,139</td><td style=\"text-align: center;\">224</td></tr><tr><th scope=\"row\" style=\"text-align: center;\">1920</th><td style=\"text-align: center;\">1,651,625</td><td style=\"text-align: center;\">197</td></tr><tr><th scope=\"row\" style=\"text-align: center;\">1925</th><td style=\"text-align: center;\">3,185,881</td><td style=\"text-align: center;\">80</td></tr></tbody></table></figure></p>\n<p>A student is using the table as part of a social studies class presentation on the US auto industry in the early twentieth century. The student notes that, according to the table, from 1910 to 1925 <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the statement?</p>","answerOptions":[{"id":"abcf72f0-d6ac-4d1e-bad3-d98d72a797ec","content":"<p>the number of cars produced increased but the number of companies producing cars decreased.</p>"},{"id":"77bece04-c7d6-4b87-8373-ade3b0e11d26","content":"<p>both the number of cars produced and the number of companies producing cars remained unchanged.</p>"},{"id":"498cfa2c-a267-472e-9bfb-5a2c5f3c4ad9","content":"<p>the number of cars produced decreased but the number of companies producing cars remained unchanged.</p>"},{"id":"27dfaf0a-bbbe-4d33-bfc9-dc38fe3dc1e2","content":"<p>both the number of cars produced and the number of companies producing cars increased.</p>"}],"keys":["abcf72f0-d6ac-4d1e-bad3-d98d72a797ec"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most effectively uses data from the table to complete the statement about the US auto industry in the early twentieth century. The table shows the number of cars produced annually and number of companies producing cars in the United States between 1910 and 1925 in increments of five years. According to the table, the number of cars produced consistently increased from one increment to the next, going from 123,990 cars in 1910 to 3,185,881 cars in 1925. At the same time, the table shows that the number of companies producing cars consistently decreased, going from 320 companies in 1910 to only 80 companies in 1925. Thus, the table shows that the number of cars produced increased from 1910 to 1925, even as the number of companies producing cars decreased.</p><p>Choice B is incorrect. The table shows that the number of cars produced in the US increased, going from 123,990 in 1910 to 3,185,881 in 1925, instead of remaining unchanged, and the table also shows that the number of companies producing cars decreased from 320 to 80 instead of remaining unchanged. Choice C is incorrect because the table indicates that the number of cars produced consistently increased from 1910 to 1925, going from 123,990 cars to 3,185,881 cars, instead of decreasing; moreover, the table shows that the number of companies producing cars from 1910 to 1925 declined from 320 to 80 instead of remaining unchanged. Choice D is incorrect because the table indicates that the number of companies producing cars consistently decreased from 1910 to 1925, going from 320 companies to only 80 companies.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323046,"updateDate":1730147323046}$SATQ$::jsonb, 1730147323046, 1730147323046),
    ($SATQ$ec93e52c$SATQ$, $SATQ$6a2a163b-95a8-46e0-80b5-f33eeff84503$SATQ$::uuid, $SATQ$f70cfde3-c39f-4b2b-9e3b-c955802c6d53$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Archaeologist Petra Vaiglova, anthropologist Xinyi Liu, and their colleagues investigated the domestication of farm animals in China during the Bronze Age (approximately 2000 to 1000 BCE). By analyzing the chemical composition of the bones of sheep, goats, and cattle from this era, the team determined that wild plants made up the bulk of sheep&rsquo;s and goats&rsquo; diets, while the cattle&rsquo;s diet consisted largely of millet, a crop cultivated by humans. The team concluded that cattle were likely raised closer to human settlements, whereas sheep and goats were allowed to roam farther away.</p>$SATQ$, $SATQ$<p>Which finding, if true, would most strongly support the team&rsquo;s conclusion?</p>$SATQ$, $SATQ$[{"id":"e2c8b035-8e01-4e08-a3f7-b8161efa13be","content":"<p>Analysis of the animal bones showed that the cattle&rsquo;s diet also consisted of wheat, which humans widely cultivated in China during the Bronze Age.</p>"},{"id":"51ca25d2-8d26-4439-8479-da691a52a331","content":"<p>Further investigation of sheep and goat bones revealed that their diets consisted of small portions of millet as well.</p>"},{"id":"2918296f-eb8b-43f7-848f-38aa5baec63f","content":"<p>Cattle&rsquo;s diets generally require larger amounts of food and a greater variety of nutrients than do sheep&rsquo;s and goats&rsquo; diets.</p>"},{"id":"3c480da4-8c1f-422c-a306-e70c7dabd58b","content":"<p>The diets of sheep, goats, and cattle were found to vary based on what the farmers in each Bronze Age settlement could grow.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["e2c8b035-8e01-4e08-a3f7-b8161efa13be"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents a finding that, if true, would most strongly support the team&rsquo;s conclusion that cattle were likely raised closer to human settlements than sheep and goats were. The text explains that Vaiglova, Liu, and their colleagues analyzed the chemical composition of sheep, goat, and cattle bones from the Bronze Age in China in order to investigate the animals&rsquo; domestication, or their adaptation from a wild state to a state in which they existed in close connection with humans. According to the text, the team&rsquo;s analysis showed that sheep and goats of the era fed largely on wild plants, whereas cattle fed on millet&mdash;importantly, a crop cultivated by humans. If analysis of the animal bones shows that the cattle&rsquo;s diet also consisted of wheat, another crop cultivated by humans in China during the Bronze Age, the finding would support the team&rsquo;s conclusion by offering additional evidence that cattle during this era fed on human-grown crops&mdash;and, by extension, that humans raised cattle relatively close to the settlements where they grew these crops, leaving goats and sheep to roam farther away in areas with wild vegetation, uncultivated by humans. </p><p>Choice B is incorrect because if it were true that sheep&rsquo;s and goats&rsquo; diets consisted of small portions of millet, which the text states was a crop cultivated by humans, the finding would suggest that sheep and goats were raised relatively close to human settlements, weakening the team&rsquo;s conclusion that cattle were likely raised closer to those settlements than sheep and goats were. Choice C is incorrect because the finding that cattle generally require more food and nutrients than do sheep and goats wouldn&rsquo;t support the team&rsquo;s conclusion that cattle were likely raised closer to human settlements than sheep and goats were. Nothing in the text suggests that cattle were incapable of obtaining sufficient food and nutrients without access to human-grown crops. Hence, even if cattle&rsquo;s diets are found to have different requirements than the diets of sheep and goats, the cattle could have met those requirements from food located far from human settlements.&nbsp;Choice D is incorrect because if it were true that the diets of sheep, goats, and cattle varied based on what the farmers in each Bronze Age settlement could grow, the finding would weaken the team&rsquo;s conclusion that cattle were likely raised closer to human settlements than sheep and goats were, suggesting instead that all three types of animals were raised close enough to human settlements to feed on those settlements&rsquo; crops. </p>$SATQ$, false, 0, $SATQ$OSP-323-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$31d5d24f-2cc1-4d75-8fc4-e78c9fa90bb4$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ec93e52c","external_id":"6a2a163b-95a8-46e0-80b5-f33eeff84503","vaultid":"f70cfde3-c39f-4b2b-9e3b-c955802c6d53","uId":"403887be-480b-4a24-8922-427d17c50f85","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Archaeologist Petra Vaiglova, anthropologist Xinyi Liu, and their colleagues investigated the domestication of farm animals in China during the Bronze Age (approximately 2000 to 1000 BCE). By analyzing the chemical composition of the bones of sheep, goats, and cattle from this era, the team determined that wild plants made up the bulk of sheep&rsquo;s and goats&rsquo; diets, while the cattle&rsquo;s diet consisted largely of millet, a crop cultivated by humans. The team concluded that cattle were likely raised closer to human settlements, whereas sheep and goats were allowed to roam farther away.</p>","stem":"<p>Which finding, if true, would most strongly support the team&rsquo;s conclusion?</p>","answerOptions":[{"id":"e2c8b035-8e01-4e08-a3f7-b8161efa13be","content":"<p>Analysis of the animal bones showed that the cattle&rsquo;s diet also consisted of wheat, which humans widely cultivated in China during the Bronze Age.</p>"},{"id":"51ca25d2-8d26-4439-8479-da691a52a331","content":"<p>Further investigation of sheep and goat bones revealed that their diets consisted of small portions of millet as well.</p>"},{"id":"2918296f-eb8b-43f7-848f-38aa5baec63f","content":"<p>Cattle&rsquo;s diets generally require larger amounts of food and a greater variety of nutrients than do sheep&rsquo;s and goats&rsquo; diets.</p>"},{"id":"3c480da4-8c1f-422c-a306-e70c7dabd58b","content":"<p>The diets of sheep, goats, and cattle were found to vary based on what the farmers in each Bronze Age settlement could grow.</p>"}],"keys":["e2c8b035-8e01-4e08-a3f7-b8161efa13be"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents a finding that, if true, would most strongly support the team&rsquo;s conclusion that cattle were likely raised closer to human settlements than sheep and goats were. The text explains that Vaiglova, Liu, and their colleagues analyzed the chemical composition of sheep, goat, and cattle bones from the Bronze Age in China in order to investigate the animals&rsquo; domestication, or their adaptation from a wild state to a state in which they existed in close connection with humans. According to the text, the team&rsquo;s analysis showed that sheep and goats of the era fed largely on wild plants, whereas cattle fed on millet&mdash;importantly, a crop cultivated by humans. If analysis of the animal bones shows that the cattle&rsquo;s diet also consisted of wheat, another crop cultivated by humans in China during the Bronze Age, the finding would support the team&rsquo;s conclusion by offering additional evidence that cattle during this era fed on human-grown crops&mdash;and, by extension, that humans raised cattle relatively close to the settlements where they grew these crops, leaving goats and sheep to roam farther away in areas with wild vegetation, uncultivated by humans. </p><p>Choice B is incorrect because if it were true that sheep&rsquo;s and goats&rsquo; diets consisted of small portions of millet, which the text states was a crop cultivated by humans, the finding would suggest that sheep and goats were raised relatively close to human settlements, weakening the team&rsquo;s conclusion that cattle were likely raised closer to those settlements than sheep and goats were. Choice C is incorrect because the finding that cattle generally require more food and nutrients than do sheep and goats wouldn&rsquo;t support the team&rsquo;s conclusion that cattle were likely raised closer to human settlements than sheep and goats were. Nothing in the text suggests that cattle were incapable of obtaining sufficient food and nutrients without access to human-grown crops. Hence, even if cattle&rsquo;s diets are found to have different requirements than the diets of sheep and goats, the cattle could have met those requirements from food located far from human settlements.&nbsp;Choice D is incorrect because if it were true that the diets of sheep, goats, and cattle varied based on what the farmers in each Bronze Age settlement could grow, the finding would weaken the team&rsquo;s conclusion that cattle were likely raised closer to human settlements than sheep and goats were, suggesting instead that all three types of animals were raised close enough to human settlements to feed on those settlements&rsquo; crops. </p>","parenttemplatename":"OSP-323-TXT","parenttemplateid":"","templateclusterid":"31d5d24f-2cc1-4d75-8fc4-e78c9fa90bb4","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959335,"updateDate":1691007959335}$SATQ$::jsonb, 1691007959335, 1691007959335),
    ($SATQ$eca09a92$SATQ$, $SATQ$a0bf3e39-c2be-4285-97d2-9668dc0fdbc2$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>If an animal has been extinct for a long time, how can scientists learn what color it was? One group of scientists came up with a possible answer. When the scientists examined the fossilized feather of an extinct bird, they found melanosomes in it. Melanosomes produce pigment, or grains of color, inside cells. Because melanosomes are shaped differently depending on which colors they produce, the scientists hypothesized that they could <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"89f42f1b-0fbc-46ad-a51a-61ad68ca6bb1","content":"<p>show how melanosomes can be found in fossils belonging to animals from other extinct species.</p>"},{"id":"868a3190-122b-4703-9823-332d4acbd041","content":"<p>determine the colors of the bird based on the appearance of the melanosomes in the feather.</p>"},{"id":"bb94f7aa-680b-4ac8-87e0-0570180d82e2","content":"<p>explain why the melanosomes in the feather were so well preserved.</p>"},{"id":"175bdb83-8ccd-470d-8188-c3c7fbb6301c","content":"<p>identify the colors of extinct animals whose fossils lack melanosomes.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["868a3190-122b-4703-9823-332d4acbd041"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of a hypothesis by one group of scientists about how to determine the colors of a long-extinct animal.  The text explains that the scientists found melanosomes in the fossilized feather of an extinct bird and that melanosomes are responsible for producing color inside cells. The text also explains that melanosomes have different shapes depending on the colors they produce. Given this information, it follows that the scientists hypothesized that they could determine the colors of the extinct bird by examining the shapes of the melanosomes in the feather.</p><p>Choice A is incorrect because the text never suggests that the scientists were seeking to show how melanosomes can be found in fossils belonging to animals from other extinct species. Rather, the text indicates that the scientists were seeking to identify an extinct bird&rsquo;s colors, and the text strongly suggests that the scientists hypothesized that they could achieve their goal by examining the shapes of the melanosomes in the bird&rsquo;s fossilized feather. Choice C is incorrect because the text never suggests that the scientists were seeking to explain why the melanosomes in the feather were so well preserved. Rather, the text indicates that the scientists were seeking to identify an extinct bird&rsquo;s colors, and the text strongly suggests that the scientists hypothesized that they could achieve their goal by examining the shapes of the melanosomes in the bird&rsquo;s fossilized feather. Choice D is incorrect because the text suggests only one method of identifying the colors of extinct animals: by examining the shapes of melanosomes found in fossils. The text doesn&rsquo;t discuss other methods for learning the colors of extinct animals and therefore provides no support for the idea that the scientists could identify the colors of extinct animals whose fossils lack melanosomes.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"eca09a92","external_id":"a0bf3e39-c2be-4285-97d2-9668dc0fdbc2","vaultid":null,"uId":"c53f1623-d6d4-49a1-8495-fdee047f8176","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>If an animal has been extinct for a long time, how can scientists learn what color it was? One group of scientists came up with a possible answer. When the scientists examined the fossilized feather of an extinct bird, they found melanosomes in it. Melanosomes produce pigment, or grains of color, inside cells. Because melanosomes are shaped differently depending on which colors they produce, the scientists hypothesized that they could <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"89f42f1b-0fbc-46ad-a51a-61ad68ca6bb1","content":"<p>show how melanosomes can be found in fossils belonging to animals from other extinct species.</p>"},{"id":"868a3190-122b-4703-9823-332d4acbd041","content":"<p>determine the colors of the bird based on the appearance of the melanosomes in the feather.</p>"},{"id":"bb94f7aa-680b-4ac8-87e0-0570180d82e2","content":"<p>explain why the melanosomes in the feather were so well preserved.</p>"},{"id":"175bdb83-8ccd-470d-8188-c3c7fbb6301c","content":"<p>identify the colors of extinct animals whose fossils lack melanosomes.</p>"}],"keys":["868a3190-122b-4703-9823-332d4acbd041"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of a hypothesis by one group of scientists about how to determine the colors of a long-extinct animal.  The text explains that the scientists found melanosomes in the fossilized feather of an extinct bird and that melanosomes are responsible for producing color inside cells. The text also explains that melanosomes have different shapes depending on the colors they produce. Given this information, it follows that the scientists hypothesized that they could determine the colors of the extinct bird by examining the shapes of the melanosomes in the feather.</p><p>Choice A is incorrect because the text never suggests that the scientists were seeking to show how melanosomes can be found in fossils belonging to animals from other extinct species. Rather, the text indicates that the scientists were seeking to identify an extinct bird&rsquo;s colors, and the text strongly suggests that the scientists hypothesized that they could achieve their goal by examining the shapes of the melanosomes in the bird&rsquo;s fossilized feather. Choice C is incorrect because the text never suggests that the scientists were seeking to explain why the melanosomes in the feather were so well preserved. Rather, the text indicates that the scientists were seeking to identify an extinct bird&rsquo;s colors, and the text strongly suggests that the scientists hypothesized that they could achieve their goal by examining the shapes of the melanosomes in the bird&rsquo;s fossilized feather. Choice D is incorrect because the text suggests only one method of identifying the colors of extinct animals: by examining the shapes of melanosomes found in fossils. The text doesn&rsquo;t discuss other methods for learning the colors of extinct animals and therefore provides no support for the idea that the scientists could identify the colors of extinct animals whose fossils lack melanosomes.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323035,"updateDate":1730147323035}$SATQ$::jsonb, 1730147323035, 1730147323035),
    ($SATQ$ed314256$SATQ$, $SATQ$9143317f-29a7-4559-930f-3895f4457c7d$SATQ$::uuid, $SATQ$5e03feba-5300-48bc-9ace-9f4b1f1e884a$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The most recent iteration of the immersive theater experience <em>Sleep No More</em>, which premiered in New York City in 2011, transforms its performance space&mdash;a five-story warehouse&mdash;into a 1930s-era hotel. Audience members, who wander through the labyrinthine venue at their own pace and follow the actors as they play out simultaneous, interweaving narrative loops, confront the impossibility of experiencing the production in its entirety. The play&rsquo;s refusal of narrative coherence thus hinges on the sense of spatial fragmentation that the venue&rsquo;s immense and intricate layout generates.</p>$SATQ$, $SATQ$<p>What does the text most strongly suggest about <em>Sleep No More</em>&rsquo;s use of its performance space?&nbsp;</p>$SATQ$, $SATQ$[{"id":"0f3baa27-e64f-4c98-a10a-2dcb8f3b2c62","content":"<p>The choice of a New York City venue likely enabled the play&rsquo;s creators to experiment with the use of theatrical space in a way that venues from earlier productions could not.&nbsp;</p>"},{"id":"699e5bda-0826-4888-8441-e5014d49e67e","content":"<p>Audience members likely find the experience of the play disappointing because they generally cannot make their way through the entire venue.</p>"},{"id":"917aa508-587e-45a8-9986-9b4fa1e73c38","content":"<p>The production&rsquo;s dependence on a particular performance environment would likely make it difficult to reproduce exactly in a different theatrical space.&nbsp;</p>"},{"id":"948908bc-baa6-4704-85b9-861e9414b7c2","content":"<p>Audience members who navigate the space according to a recommended itinerary will likely have a better grasp of the play&rsquo;s narrative than audience members who depart from that itinerary.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["917aa508-587e-45a8-9986-9b4fa1e73c38"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The text says that the production&rsquo;s use of its large, winding space has a very specific effect on the audience. Given that the space itself is so important to creating this effect, it would be difficult to reproduce the production in a different space.</p><p>Choice A is incorrect. The fact that the venue is in New York City isn&rsquo;t connected to the experimental nature of the performance. It&rsquo;s the size of the venue, not its location in New York, that affects the theatrical experience. Choice B is incorrect. The text never suggests that audience members are disappointed because they can&rsquo;t see the entire production. In fact, it suggests that that&rsquo;s an important part of the experience. Choice D is incorrect. The text doesn&rsquo;t mention a recommended itinerary for audience members.</p>$SATQ$, false, 0, $SATQ$OSP-KA-CID-H006$SATQ$, $SATQ$$SATQ$, $SATQ$ece8c29d-afa9-4254-bd9a-9fbfbc5d1876$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ed314256","external_id":"9143317f-29a7-4559-930f-3895f4457c7d","vaultid":"5e03feba-5300-48bc-9ace-9f4b1f1e884a","uId":"04307ac2-5b7b-43e3-832a-1ee4b90a1226","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The most recent iteration of the immersive theater experience <em>Sleep No More</em>, which premiered in New York City in 2011, transforms its performance space&mdash;a five-story warehouse&mdash;into a 1930s-era hotel. Audience members, who wander through the labyrinthine venue at their own pace and follow the actors as they play out simultaneous, interweaving narrative loops, confront the impossibility of experiencing the production in its entirety. The play&rsquo;s refusal of narrative coherence thus hinges on the sense of spatial fragmentation that the venue&rsquo;s immense and intricate layout generates.</p>","stem":"<p>What does the text most strongly suggest about <em>Sleep No More</em>&rsquo;s use of its performance space?&nbsp;</p>","answerOptions":[{"id":"0f3baa27-e64f-4c98-a10a-2dcb8f3b2c62","content":"<p>The choice of a New York City venue likely enabled the play&rsquo;s creators to experiment with the use of theatrical space in a way that venues from earlier productions could not.&nbsp;</p>"},{"id":"699e5bda-0826-4888-8441-e5014d49e67e","content":"<p>Audience members likely find the experience of the play disappointing because they generally cannot make their way through the entire venue.</p>"},{"id":"917aa508-587e-45a8-9986-9b4fa1e73c38","content":"<p>The production&rsquo;s dependence on a particular performance environment would likely make it difficult to reproduce exactly in a different theatrical space.&nbsp;</p>"},{"id":"948908bc-baa6-4704-85b9-861e9414b7c2","content":"<p>Audience members who navigate the space according to a recommended itinerary will likely have a better grasp of the play&rsquo;s narrative than audience members who depart from that itinerary.</p>"}],"keys":["917aa508-587e-45a8-9986-9b4fa1e73c38"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The text says that the production&rsquo;s use of its large, winding space has a very specific effect on the audience. Given that the space itself is so important to creating this effect, it would be difficult to reproduce the production in a different space.</p><p>Choice A is incorrect. The fact that the venue is in New York City isn&rsquo;t connected to the experimental nature of the performance. It&rsquo;s the size of the venue, not its location in New York, that affects the theatrical experience. Choice B is incorrect. The text never suggests that audience members are disappointed because they can&rsquo;t see the entire production. In fact, it suggests that that&rsquo;s an important part of the experience. Choice D is incorrect. The text doesn&rsquo;t mention a recommended itinerary for audience members.</p>","parenttemplatename":"OSP-KA-CID-H006","parenttemplateid":"","templateclusterid":"ece8c29d-afa9-4254-bd9a-9fbfbc5d1876","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959360,"updateDate":1691007959360}$SATQ$::jsonb, 1691007959360, 1691007959360),
    ($SATQ$ed586475$SATQ$, $SATQ$7d4a4c83-50ae-47ab-9d3d-a67b0cc584c2$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p><em>There Is Confusion</em> is a 1924 novel by Jessie Redmon Fauset. In the novel, the narrator portrays the character Joanna as someone who admires ambition in other people to the exclusion of all other qualities: <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from <em>There Is Confusion</em> most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"b417c5fb-56fb-49b8-abd6-4641bbdd43dd","content":"<p>&ldquo;Joanna was mightily interested in people who had a &lsquo;purpose&rsquo; in life. Otherwise not at all.&rdquo;&nbsp;</p>"},{"id":"e0472a74-365e-4001-ad9c-91261010511e","content":"<p><span>&ldquo;Indeed from the very beginning Joanna showed her preference for her father.&rdquo;&nbsp;</span></p>"},{"id":"00b53d94-a91f-4de4-8876-4439ff1286fb","content":"<p>&ldquo;Joanna was like her father not only so far as ambition was concerned but also in her willingness to work.&rdquo;&nbsp;</p>"},{"id":"e9a3d9d9-2317-4a45-8c2a-375e0119dd34","content":"<p>&ldquo;She had a good sense of logic, a strong power of concentration, and a remarkably retentive and visualizing memory.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["b417c5fb-56fb-49b8-abd6-4641bbdd43dd"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most effectively presents a quotation from <em>There Is Confusion </em>that illustrates the claim that the narrator portrays Joanna as admiring the quality of ambition, or the determination to achieve something, and no other qualities in other people. By describing Joanna as not being interested in people unless they have "a &lsquo;purpose&rsquo; in life"&mdash;that is, a goal they are determined to achieve&mdash;in which case she is very interested in them, the quotation reveals that Joanna cares only about others&rsquo; ambition.</p><p>Choice B is incorrect because this quotation indicates only that Joanna has a preference for her father, without giving a reason for that preference; therefore, it doesn&rsquo;t illustrate the claim that Joanna cares only about others&rsquo; ambition. Choice C is incorrect because this quotation doesn&rsquo;t illustrate that Joanna greatly admires the quality of ambition in others; it refers to Joanna&rsquo;s similarity to her father "so far as ambition was concerned" but doesn&rsquo;t reveal how she (or her father) views that quality. Choice D is incorrect because this quotation describes qualities Joanna possesses&mdash;praising her logic, concentration, and memory&mdash;instead of Joanna&rsquo;s interest in other people&rsquo;s qualities.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"ed586475","external_id":"7d4a4c83-50ae-47ab-9d3d-a67b0cc584c2","vaultid":null,"uId":"5d31bf21-0a7c-41ba-9da5-c76cc6fde600","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p><em>There Is Confusion</em> is a 1924 novel by Jessie Redmon Fauset. In the novel, the narrator portrays the character Joanna as someone who admires ambition in other people to the exclusion of all other qualities: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from <em>There Is Confusion</em> most effectively illustrates the claim?</p>","answerOptions":[{"id":"b417c5fb-56fb-49b8-abd6-4641bbdd43dd","content":"<p>&ldquo;Joanna was mightily interested in people who had a &lsquo;purpose&rsquo; in life. Otherwise not at all.&rdquo;&nbsp;</p>"},{"id":"e0472a74-365e-4001-ad9c-91261010511e","content":"<p><span>&ldquo;Indeed from the very beginning Joanna showed her preference for her father.&rdquo;&nbsp;</span></p>"},{"id":"00b53d94-a91f-4de4-8876-4439ff1286fb","content":"<p>&ldquo;Joanna was like her father not only so far as ambition was concerned but also in her willingness to work.&rdquo;&nbsp;</p>"},{"id":"e9a3d9d9-2317-4a45-8c2a-375e0119dd34","content":"<p>&ldquo;She had a good sense of logic, a strong power of concentration, and a remarkably retentive and visualizing memory.&rdquo;</p>"}],"keys":["b417c5fb-56fb-49b8-abd6-4641bbdd43dd"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most effectively presents a quotation from <em>There Is Confusion </em>that illustrates the claim that the narrator portrays Joanna as admiring the quality of ambition, or the determination to achieve something, and no other qualities in other people. By describing Joanna as not being interested in people unless they have \"a &lsquo;purpose&rsquo; in life\"&mdash;that is, a goal they are determined to achieve&mdash;in which case she is very interested in them, the quotation reveals that Joanna cares only about others&rsquo; ambition.</p><p>Choice B is incorrect because this quotation indicates only that Joanna has a preference for her father, without giving a reason for that preference; therefore, it doesn&rsquo;t illustrate the claim that Joanna cares only about others&rsquo; ambition. Choice C is incorrect because this quotation doesn&rsquo;t illustrate that Joanna greatly admires the quality of ambition in others; it refers to Joanna&rsquo;s similarity to her father \"so far as ambition was concerned\" but doesn&rsquo;t reveal how she (or her father) views that quality. Choice D is incorrect because this quotation describes qualities Joanna possesses&mdash;praising her logic, concentration, and memory&mdash;instead of Joanna&rsquo;s interest in other people&rsquo;s qualities.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323045,"updateDate":1730147323045}$SATQ$::jsonb, 1730147323045, 1730147323045),
    ($SATQ$ede3f942$SATQ$, $SATQ$f4a26f2b-ff3e-4afc-a69b-dfdccf46bdf3$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Total Areas of Five Tribal Nations in California</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Tribal nation</th><th scope="col" style="text-align: center;vertical-align: bottom;">Location</th><th scope="col" style="text-align: center;vertical-align: bottom;">Area (square miles)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Hoopa Valley Tribe</th><td>Northern California</td><td style="text-align: center;">141.68</td></tr><tr><th scope="row" style="text-align: left;">La Jolla Band of Luise&ntilde;o Indians</th><td>Southern California</td><td style="text-align: center;">13.50</td></tr><tr><th scope="row" style="text-align: left;">Pauma Band of Luise&ntilde;o Mission Indians</th><td>Southern California</td><td style="text-align: center;">9.36</td></tr><tr><th scope="row" style="text-align: left;">Agua Caliente Band of Cahuilla Indians</th><td>Northern California</td><td style="text-align: center;">53.68</td></tr><tr><th scope="row" style="text-align: left;">Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians</th><td>Southern California</td><td style="text-align: center;">39.21</td></tr></tbody></table></figure></p>
<p>In what is now the state of California, there are over 100 tribal nations. One of the largest, the Hoopa Valley Tribe, covers 141.68 square miles in the northern part of the state. However, most tribal nations in California are less than 50 square miles in total area. For example, the total area of the Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians in Southern California is <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to support the statement?</p>$SATQ$, $SATQ$[{"id":"d5834a1a-2dd1-488f-b93e-a0577f7ca8dc","content":"<p>13.50 square miles.</p>"},{"id":"070a0ee8-ce17-43af-b0dd-cc5140fbd78b","content":"<p>53.68 square miles.</p>"},{"id":"2bf0baa4-4ae7-4a92-9597-c8ade593d9de","content":"<p>9.36 square miles.</p>"},{"id":"1e6caac5-b64d-43f8-b983-8f07fec93303","content":"<p>39.21 square miles.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["1e6caac5-b64d-43f8-b983-8f07fec93303"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most effectively uses data from the table to support the statement about the tribal nation of Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians in California. The text states that most tribal nations in California are less than 50 square miles in total area and provides Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians as an example. According to the table, the tribal nation of Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians covers 39.21 square miles in Southern California, which is less than 50 square miles.</p><p>Choice A is incorrect because it cites the area of La Jolla Band of Luise&ntilde;o Indians (13.50 square miles), not that of Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians. Choice B is incorrect because it cites the area of the Agua Caliente Band of Cahuilla Indians (53.68 square miles), not that of Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians. Additionally, this area is greater than 50 square miles and therefore wouldn&rsquo;t be an effective example for illustrating the text&rsquo;s statement that most tribal nations in California are less than 50 square miles in total area. Choice C is incorrect because it cites the area of the Pauma Band of Luise&ntilde;o Mission Indians (9.36 square miles), not that of Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"ede3f942","external_id":"f4a26f2b-ff3e-4afc-a69b-dfdccf46bdf3","vaultid":null,"uId":"c5bd0394-bb68-48c1-8c96-4db0162b8e05","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Total Areas of Five Tribal Nations in California</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Tribal nation</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Location</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Area (square miles)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Hoopa Valley Tribe</th><td>Northern California</td><td style=\"text-align: center;\">141.68</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">La Jolla Band of Luise&ntilde;o Indians</th><td>Southern California</td><td style=\"text-align: center;\">13.50</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Pauma Band of Luise&ntilde;o Mission Indians</th><td>Southern California</td><td style=\"text-align: center;\">9.36</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Agua Caliente Band of Cahuilla Indians</th><td>Northern California</td><td style=\"text-align: center;\">53.68</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians</th><td>Southern California</td><td style=\"text-align: center;\">39.21</td></tr></tbody></table></figure></p>\n<p>In what is now the state of California, there are over 100 tribal nations. One of the largest, the Hoopa Valley Tribe, covers 141.68 square miles in the northern part of the state. However, most tribal nations in California are less than 50 square miles in total area. For example, the total area of the Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians in Southern California is <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to support the statement?</p>","answerOptions":[{"id":"d5834a1a-2dd1-488f-b93e-a0577f7ca8dc","content":"<p>13.50 square miles.</p>"},{"id":"070a0ee8-ce17-43af-b0dd-cc5140fbd78b","content":"<p>53.68 square miles.</p>"},{"id":"2bf0baa4-4ae7-4a92-9597-c8ade593d9de","content":"<p>9.36 square miles.</p>"},{"id":"1e6caac5-b64d-43f8-b983-8f07fec93303","content":"<p>39.21 square miles.</p>"}],"keys":["1e6caac5-b64d-43f8-b983-8f07fec93303"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most effectively uses data from the table to support the statement about the tribal nation of Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians in California. The text states that most tribal nations in California are less than 50 square miles in total area and provides Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians as an example. According to the table, the tribal nation of Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians covers 39.21 square miles in Southern California, which is less than 50 square miles.</p><p>Choice A is incorrect because it cites the area of La Jolla Band of Luise&ntilde;o Indians (13.50 square miles), not that of Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians. Choice B is incorrect because it cites the area of the Agua Caliente Band of Cahuilla Indians (53.68 square miles), not that of Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians. Additionally, this area is greater than 50 square miles and therefore wouldn&rsquo;t be an effective example for illustrating the text&rsquo;s statement that most tribal nations in California are less than 50 square miles in total area. Choice C is incorrect because it cites the area of the Pauma Band of Luise&ntilde;o Mission Indians (9.36 square miles), not that of Los Coyotes Band of Cahuilla and Cupe&ntilde;o Indians.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061193,"updateDate":1755117061193}$SATQ$::jsonb, 1755117061193, 1755117061193),
    ($SATQ$ee41d7e0$SATQ$, $SATQ$2726ae9a-1dbe-4d18-bd8b-ee2cc3808a0d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Arthropods&mdash;brine shrimp, hawk moths, and many other invertebrate animals&mdash;have a nervous system made up of a brain, nerve cord, and other nerves. Researchers have gained insights about this system in ancient arthropods from traces found in various fossils. For example, in a study of two fossils of the extinct arthropod species <em>Mollisonia symmetrica</em>, Javier Ortega-Hern&aacute;ndez, James Weaver, and team observed clear signs of a nerve cord. They also saw possible indications of a synganglion, a brain-like mass of nerves. Researchers hope to identify more features of the nervous systems of prehistoric arthropods as additional fossils are found.</p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"de1c56dd-bd86-4fab-959a-55397f2c7efc","content":"<p>There are several similarities between the brains of hawk moths and the brains of brine shrimp.</p>"},{"id":"123e7ba0-abbb-414d-bcb6-136e3a5b7263","content":"<p>Fossil evidence can contribute to the understanding of the nervous system in ancient arthropods.</p>"},{"id":"608852c0-f10b-4501-b86f-72b90a2cbda8","content":"<p>Newly discovered fossils suggest that ancient hawk moths and ancient brine shrimp had spines.</p>"},{"id":"565a6459-5ed3-45e9-839a-2336fc371888","content":"<p>Researchers need to focus on finding more fossils of ancient arthropods.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["123e7ba0-abbb-414d-bcb6-136e3a5b7263"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most accurately states the main idea of the text. The text states that researchers have used fossils to learn about the nervous systems of ancient arthropods. It then provides a specific example of researchers studying fossils of <em>Mollisonia symmetrica</em> and finding evidence of a nerve cord and possibly a synganglion (a brain-like mass of nerves). The text concludes by noting that researchers hope to discover more features of prehistoric arthropods&rsquo; nervous systems "as additional fossils are found." Thus, the main idea of the text is that fossil evidence can contribute to the understanding of the nervous system in ancient arthropods.</p><p>Choice A is incorrect because the text doesn&rsquo;t compare the brains of hawk moths and brine shrimp. These animals are merely mentioned as examples of arthropods in the opening sentence, and the text doesn&rsquo;t go on to discuss any similarities between their brains. Choice C is incorrect because the text discusses nervous systems, not spines, in ancient arthropods, and it doesn&rsquo;t specifically mention findings about ancient hawk moths or brine shrimp. Choice D is incorrect. While the text concludes by noting that researchers aim to discover additional characteristics of prehistoric arthropods&rsquo; nervous systems as more fossils are uncovered, this statement doesn&rsquo;t suggest that researchers need to focus on finding more fossils. Rather, it simply indicates that researchers expect to learn more about this topic as additional fossils are discovered. Moreover, the statement is just a detail that supports the main idea; it&rsquo;s not the main idea itself.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"ee41d7e0","external_id":"2726ae9a-1dbe-4d18-bd8b-ee2cc3808a0d","vaultid":null,"uId":"e9f918ab-341f-469e-bca7-2202c6a016ee","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Arthropods&mdash;brine shrimp, hawk moths, and many other invertebrate animals&mdash;have a nervous system made up of a brain, nerve cord, and other nerves. Researchers have gained insights about this system in ancient arthropods from traces found in various fossils. For example, in a study of two fossils of the extinct arthropod species <em>Mollisonia symmetrica</em>, Javier Ortega-Hern&aacute;ndez, James Weaver, and team observed clear signs of a nerve cord. They also saw possible indications of a synganglion, a brain-like mass of nerves. Researchers hope to identify more features of the nervous systems of prehistoric arthropods as additional fossils are found.</p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"de1c56dd-bd86-4fab-959a-55397f2c7efc","content":"<p>There are several similarities between the brains of hawk moths and the brains of brine shrimp.</p>"},{"id":"123e7ba0-abbb-414d-bcb6-136e3a5b7263","content":"<p>Fossil evidence can contribute to the understanding of the nervous system in ancient arthropods.</p>"},{"id":"608852c0-f10b-4501-b86f-72b90a2cbda8","content":"<p>Newly discovered fossils suggest that ancient hawk moths and ancient brine shrimp had spines.</p>"},{"id":"565a6459-5ed3-45e9-839a-2336fc371888","content":"<p>Researchers need to focus on finding more fossils of ancient arthropods.</p>"}],"keys":["123e7ba0-abbb-414d-bcb6-136e3a5b7263"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most accurately states the main idea of the text. The text states that researchers have used fossils to learn about the nervous systems of ancient arthropods. It then provides a specific example of researchers studying fossils of <em>Mollisonia symmetrica</em> and finding evidence of a nerve cord and possibly a synganglion (a brain-like mass of nerves). The text concludes by noting that researchers hope to discover more features of prehistoric arthropods&rsquo; nervous systems \"as additional fossils are found.\" Thus, the main idea of the text is that fossil evidence can contribute to the understanding of the nervous system in ancient arthropods.</p><p>Choice A is incorrect because the text doesn&rsquo;t compare the brains of hawk moths and brine shrimp. These animals are merely mentioned as examples of arthropods in the opening sentence, and the text doesn&rsquo;t go on to discuss any similarities between their brains. Choice C is incorrect because the text discusses nervous systems, not spines, in ancient arthropods, and it doesn&rsquo;t specifically mention findings about ancient hawk moths or brine shrimp. Choice D is incorrect. While the text concludes by noting that researchers aim to discover additional characteristics of prehistoric arthropods&rsquo; nervous systems as more fossils are uncovered, this statement doesn&rsquo;t suggest that researchers need to focus on finding more fossils. Rather, it simply indicates that researchers expect to learn more about this topic as additional fossils are discovered. Moreover, the statement is just a detail that supports the main idea; it&rsquo;s not the main idea itself.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061176,"updateDate":1755117061176}$SATQ$::jsonb, 1755117061176, 1755117061176),
    ($SATQ$f1bfbed3$SATQ$, $SATQ$52a8f1cb-bff4-4dcb-b455-fbc202e8513c$SATQ$::uuid, $SATQ$e7f3e1d5-cadf-4f44-b54d-9e512e53743c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Marta Coll and colleagues&rsquo; 2010 Mediterranean Sea biodiversity census reported approximately 17,000 species, nearly double the number reported in Carlo Bianchi and Carla Morri&rsquo;s 2000 census&mdash;a difference only partly attributable to the description of new invertebrate species in the interim. Another factor is that the morphological variability of microorganisms is poorly understood compared to that of vertebrates, invertebrates, plants, and algae, creating uncertainty about how to evaluate microorganisms as species. Researchers&rsquo; decisions on such matters therefore can be highly consequential. Indeed, the two censuses reported similar counts of vertebrate, plant, and algal species, suggesting that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"21140db9-ae9f-4478-be55-2511c86ebdd0","content":"<p>Coll and colleagues reported a much higher number of species than Bianchi and Morri did largely due to the inclusion of invertebrate species that had not been described at the time of Bianchi and Morri&rsquo;s census.</p>"},{"id":"6cbd8139-b9e9-4afc-a2a3-4c5554cdabb4","content":"<p>some differences observed in microorganisms may have been treated as variations within species by Bianchi and Morri but treated as indicative of distinct species by Coll and colleagues.</p>"},{"id":"78fe5f7b-acb6-4e48-9ca0-b7f8d98387a1","content":"<p>Bianchi and Morri may have been less sensitive to the degree of morphological variation displayed within a typical species of microorganism than Coll and colleagues were.</p>"},{"id":"a9e10939-c800-48f3-8989-7b22758b9779","content":"<p>the absence of clarity regarding how to differentiate among species of microorganisms may have resulted in Coll and colleagues underestimating the number of microorganism species.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["6cbd8139-b9e9-4afc-a2a3-4c5554cdabb4"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it presents the conclusion that most logically completes the text&rsquo;s discussion of the different counts of species in the Mediterranean Sea. The text states that Coll and colleagues reported almost double the number of species that Bianchi and Morri reported in their study ten years earlier. According to the text, this difference can only be partly attributed to new invertebrate species being described in the years between the two studies, which means there must be an additional factor that made Coll and colleagues&rsquo; count so much higher than Bianchi and Morri&rsquo;s count. The text goes on to explain that factor: researchers have a relatively poor understanding of microorganisms&rsquo; morphological variability, or the differences in microorganisms&rsquo; structure and form. This poor understanding makes it hard to classify microorganisms by species and means that researchers&rsquo; decisions about classifying microorganisms can have a large effect on the overall species counts that researchers report. Additionally, the text says that the two censuses reported similar numbers of vertebrate, plant, and algal species, which means that the difference in overall species did not come from differences in those categories. Given all this information, it most logically follows that Coll and colleagues may have treated some of the differences among microorganisms as indicative of the microorganisms being different species, whereas Bianchi and Morri treated those differences as variations within species, resulting in Coll and colleagues reporting many more species than Bianchi and Morri did. </p><p>Choice A is incorrect because the text explicitly addresses this issue by stating that the description of new invertebrate species in the years between the two studies can explain only part of the difference in the number of species reported by the studies. The focus of the text is on explaining the difference between Coll and colleagues&rsquo; count and Bianchi and Morri&rsquo;s count that cannot be accounted for by the inclusion of invertebrate species that had not been described at the time of Bianchi and Morri&rsquo;s study.&nbsp;Choice C is incorrect because nothing in the text suggests that Bianchi and Morri may have been less sensitive to how much the form and structure of microorganisms vary within the same species than Coll and colleagues were. If Bianchi and Morri had been less sensitive to within-species variation than Coll and colleagues were, Bianchi and Morri would likely have reported more species than Coll and colleagues did, since less sensitivity to within-species variation would lead researchers to classify as different species microorganisms that more sensitive researchers would classify as variations within the same species. The text indicates, however, that Bianchi and Morri reported far fewer species than Coll and colleagues did; since the text also excludes other explanations for this difference, it suggests that in fact Bianchi and Morri were more sensitive to within-species variation than Coll and colleagues were, leading Bianchi and Morri to report fewer overall species.&nbsp;Choice D is incorrect because the text is focused on explaining why Coll and colleagues reported many more species than Bianchi and Morri did, and an underestimate of the number of microorganism species by Coll and colleagues would not explain that difference&mdash;it would suggest, in fact, that the difference in the number of species should have been even larger.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-065-INF$SATQ$, $SATQ$$SATQ$, $SATQ$dea7b827-4e36-444d-b229-9205873fc758$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f1bfbed3","external_id":"52a8f1cb-bff4-4dcb-b455-fbc202e8513c","vaultid":"e7f3e1d5-cadf-4f44-b54d-9e512e53743c","uId":"0031fa19-22a1-47ff-a1e9-3d32db74dda6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Marta Coll and colleagues&rsquo; 2010 Mediterranean Sea biodiversity census reported approximately 17,000 species, nearly double the number reported in Carlo Bianchi and Carla Morri&rsquo;s 2000 census&mdash;a difference only partly attributable to the description of new invertebrate species in the interim. Another factor is that the morphological variability of microorganisms is poorly understood compared to that of vertebrates, invertebrates, plants, and algae, creating uncertainty about how to evaluate microorganisms as species. Researchers&rsquo; decisions on such matters therefore can be highly consequential. Indeed, the two censuses reported similar counts of vertebrate, plant, and algal species, suggesting that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"21140db9-ae9f-4478-be55-2511c86ebdd0","content":"<p>Coll and colleagues reported a much higher number of species than Bianchi and Morri did largely due to the inclusion of invertebrate species that had not been described at the time of Bianchi and Morri&rsquo;s census.</p>"},{"id":"6cbd8139-b9e9-4afc-a2a3-4c5554cdabb4","content":"<p>some differences observed in microorganisms may have been treated as variations within species by Bianchi and Morri but treated as indicative of distinct species by Coll and colleagues.</p>"},{"id":"78fe5f7b-acb6-4e48-9ca0-b7f8d98387a1","content":"<p>Bianchi and Morri may have been less sensitive to the degree of morphological variation displayed within a typical species of microorganism than Coll and colleagues were.</p>"},{"id":"a9e10939-c800-48f3-8989-7b22758b9779","content":"<p>the absence of clarity regarding how to differentiate among species of microorganisms may have resulted in Coll and colleagues underestimating the number of microorganism species.</p>"}],"keys":["6cbd8139-b9e9-4afc-a2a3-4c5554cdabb4"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it presents the conclusion that most logically completes the text&rsquo;s discussion of the different counts of species in the Mediterranean Sea. The text states that Coll and colleagues reported almost double the number of species that Bianchi and Morri reported in their study ten years earlier. According to the text, this difference can only be partly attributed to new invertebrate species being described in the years between the two studies, which means there must be an additional factor that made Coll and colleagues&rsquo; count so much higher than Bianchi and Morri&rsquo;s count. The text goes on to explain that factor: researchers have a relatively poor understanding of microorganisms&rsquo; morphological variability, or the differences in microorganisms&rsquo; structure and form. This poor understanding makes it hard to classify microorganisms by species and means that researchers&rsquo; decisions about classifying microorganisms can have a large effect on the overall species counts that researchers report. Additionally, the text says that the two censuses reported similar numbers of vertebrate, plant, and algal species, which means that the difference in overall species did not come from differences in those categories. Given all this information, it most logically follows that Coll and colleagues may have treated some of the differences among microorganisms as indicative of the microorganisms being different species, whereas Bianchi and Morri treated those differences as variations within species, resulting in Coll and colleagues reporting many more species than Bianchi and Morri did. </p><p>Choice A is incorrect because the text explicitly addresses this issue by stating that the description of new invertebrate species in the years between the two studies can explain only part of the difference in the number of species reported by the studies. The focus of the text is on explaining the difference between Coll and colleagues&rsquo; count and Bianchi and Morri&rsquo;s count that cannot be accounted for by the inclusion of invertebrate species that had not been described at the time of Bianchi and Morri&rsquo;s study.&nbsp;Choice C is incorrect because nothing in the text suggests that Bianchi and Morri may have been less sensitive to how much the form and structure of microorganisms vary within the same species than Coll and colleagues were. If Bianchi and Morri had been less sensitive to within-species variation than Coll and colleagues were, Bianchi and Morri would likely have reported more species than Coll and colleagues did, since less sensitivity to within-species variation would lead researchers to classify as different species microorganisms that more sensitive researchers would classify as variations within the same species. The text indicates, however, that Bianchi and Morri reported far fewer species than Coll and colleagues did; since the text also excludes other explanations for this difference, it suggests that in fact Bianchi and Morri were more sensitive to within-species variation than Coll and colleagues were, leading Bianchi and Morri to report fewer overall species.&nbsp;Choice D is incorrect because the text is focused on explaining why Coll and colleagues reported many more species than Bianchi and Morri did, and an underestimate of the number of microorganism species by Coll and colleagues would not explain that difference&mdash;it would suggest, in fact, that the difference in the number of species should have been even larger.&nbsp;</p>","parenttemplatename":"OSP-065-INF","parenttemplateid":"","templateclusterid":"dea7b827-4e36-444d-b229-9205873fc758","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959325,"updateDate":1691007959325}$SATQ$::jsonb, 1691007959325, 1691007959325),
    ($SATQ$f2208f98$SATQ$, $SATQ$186b2a9e-0ace-47a7-b2d5-4db88f390327$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>When Kenyan writer Ngũgĩ wa Thiong&rsquo;o, who had previously published four novels in English, began writing in his native language, Gĩkũyũ, in the 1970s, several fellow writers and critics cautioned that doing so might make his works inaccessible outside his own community. Some noted that Kiswahili&mdash;widely spoken in Kenya and elsewhere in Africa&mdash;would be a more practical choice. Rejecting their arguments, Ngũgĩ went on to author dozens of acclaimed works in Gĩkũyũ that have been translated into a total of more than thirty languages.</p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"5083f78a-6858-4763-a0fe-158b8ae73354","content":"<p>The reaction to Ngũgĩ&rsquo;s rejection of English illustrates that some literary experts believe that fame is most easily gained by writing in a widely understood language, such as Gĩkũyũ.</p>"},{"id":"ae11b317-deaa-42c0-93e2-c6515cf5390d","content":"<p>Although Ngũgĩ insisted on publishing his first works in Gĩkũyũ, they have since been translated into many other languages.</p>"},{"id":"c3ffdf6f-326b-41c9-a0b1-72d3c23d23be","content":"<p>Although Ngũgĩ&rsquo;s decision to write in Gĩkũyũ was met with some skepticism, it didn&rsquo;t prevent him from achieving literary success.</p>"},{"id":"b71f3697-a453-4b69-bb6c-cdcce870dd7e","content":"<p>In the 1970s, Ngũgĩ became convinced that literature ought to be written in authors&rsquo; native languages, and he proceeded to publish many works in Gĩkũyũ.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["c3ffdf6f-326b-41c9-a0b1-72d3c23d23be"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most accurately states the main idea of the text. The text begins by explaining that Kenyan writer Ngũgĩ wa Thiong&rsquo;o had published four novels in English before he began writing in his native language, Gĩkũyũ, in the 1970s. The text then explains that fellow writers and critics were skeptical of this decision, warning that the choice to publish in his native language, which the text implies isn&rsquo;t widely understood, would limit his readership. The text concludes by stating that despite those warnings, Ngũgĩ proceeded to publish several acclaimed novels in Gĩkũyũ that were translated into several languages, suggesting that Ngũgĩ&rsquo;s works in Gĩkũyũ achieved literary success in the forms of critical recognition and a wide international readership. Thus, the main idea is that although Ngũgĩ&rsquo;s decision to write in Gĩkũyũ was met with some skepticism, this choice didn&rsquo;t prevent him from achieving literary success.</p><p>Choice A is incorrect because it contradicts the description of Gĩkũyũ provided in the text. Rather than indicating that Gĩkũyũ is a widely understood language, as this choice claims, the text states that colleagues cautioned Ngũgĩ that writing in Gĩkũyũ instead of English &ldquo;might make his works inaccessible outside his own community.&rdquo; Furthermore, the text contrasts the choice of Gĩkũyũ with another alternative to English, Kiswahili, which the text indicates is &ldquo;a more practical choice&rdquo; given that it is &ldquo;widely spoken in Kenya and elsewhere in Africa.&rdquo; Choice B is incorrect because it contradicts information in the text. Although the text states that the novels Ngũgĩ published in Gĩkũyũ were later translated into other languages, the text explicitly states that Ngũgĩ had previously published four novels in English before he began writing in Gĩkũyũ in the 1970s. Thus, his first works were published in English, not Gĩkũyũ. Choice D is incorrect. The text doesn&rsquo;t address what motivated Ngũgĩ&rsquo;s choice to publish in his native Gĩkũyũ, and nothing in the text suggests that he intended for other authors to follow his example.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f2208f98","external_id":"186b2a9e-0ace-47a7-b2d5-4db88f390327","vaultid":null,"uId":"f3ac9fca-2188-42cd-b847-b63f0b81a1c4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>When Kenyan writer Ngũgĩ wa Thiong&rsquo;o, who had previously published four novels in English, began writing in his native language, Gĩkũyũ, in the 1970s, several fellow writers and critics cautioned that doing so might make his works inaccessible outside his own community. Some noted that Kiswahili&mdash;widely spoken in Kenya and elsewhere in Africa&mdash;would be a more practical choice. Rejecting their arguments, Ngũgĩ went on to author dozens of acclaimed works in Gĩkũyũ that have been translated into a total of more than thirty languages.</p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"5083f78a-6858-4763-a0fe-158b8ae73354","content":"<p>The reaction to Ngũgĩ&rsquo;s rejection of English illustrates that some literary experts believe that fame is most easily gained by writing in a widely understood language, such as Gĩkũyũ.</p>"},{"id":"ae11b317-deaa-42c0-93e2-c6515cf5390d","content":"<p>Although Ngũgĩ insisted on publishing his first works in Gĩkũyũ, they have since been translated into many other languages.</p>"},{"id":"c3ffdf6f-326b-41c9-a0b1-72d3c23d23be","content":"<p>Although Ngũgĩ&rsquo;s decision to write in Gĩkũyũ was met with some skepticism, it didn&rsquo;t prevent him from achieving literary success.</p>"},{"id":"b71f3697-a453-4b69-bb6c-cdcce870dd7e","content":"<p>In the 1970s, Ngũgĩ became convinced that literature ought to be written in authors&rsquo; native languages, and he proceeded to publish many works in Gĩkũyũ.</p>"}],"keys":["c3ffdf6f-326b-41c9-a0b1-72d3c23d23be"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most accurately states the main idea of the text. The text begins by explaining that Kenyan writer Ngũgĩ wa Thiong&rsquo;o had published four novels in English before he began writing in his native language, Gĩkũyũ, in the 1970s. The text then explains that fellow writers and critics were skeptical of this decision, warning that the choice to publish in his native language, which the text implies isn&rsquo;t widely understood, would limit his readership. The text concludes by stating that despite those warnings, Ngũgĩ proceeded to publish several acclaimed novels in Gĩkũyũ that were translated into several languages, suggesting that Ngũgĩ&rsquo;s works in Gĩkũyũ achieved literary success in the forms of critical recognition and a wide international readership. Thus, the main idea is that although Ngũgĩ&rsquo;s decision to write in Gĩkũyũ was met with some skepticism, this choice didn&rsquo;t prevent him from achieving literary success.</p><p>Choice A is incorrect because it contradicts the description of Gĩkũyũ provided in the text. Rather than indicating that Gĩkũyũ is a widely understood language, as this choice claims, the text states that colleagues cautioned Ngũgĩ that writing in Gĩkũyũ instead of English &ldquo;might make his works inaccessible outside his own community.&rdquo; Furthermore, the text contrasts the choice of Gĩkũyũ with another alternative to English, Kiswahili, which the text indicates is &ldquo;a more practical choice&rdquo; given that it is &ldquo;widely spoken in Kenya and elsewhere in Africa.&rdquo; Choice B is incorrect because it contradicts information in the text. Although the text states that the novels Ngũgĩ published in Gĩkũyũ were later translated into other languages, the text explicitly states that Ngũgĩ had previously published four novels in English before he began writing in Gĩkũyũ in the 1970s. Thus, his first works were published in English, not Gĩkũyũ. Choice D is incorrect. The text doesn&rsquo;t address what motivated Ngũgĩ&rsquo;s choice to publish in his native Gĩkũyũ, and nothing in the text suggests that he intended for other authors to follow his example.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771167,"updateDate":1776362771167}$SATQ$::jsonb, 1776362771167, 1776362771167),
    ($SATQ$f2250478$SATQ$, $SATQ$1830f378-1723-46f1-b0c3-3f7fd3b742f3$SATQ$::uuid, $SATQ$eff482f7-c758-42d8-9917-829c9da9b005$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Among social animals that care for their young, such as chickens, macaque monkeys, and humans, newborns appear to show an innate attraction to faces and face-like stimuli. Elisabetta Versace and her colleagues used an image of three black dots arranged in the shape of eyes and a nose or mouth to test whether this trait also occurs in <em>Testudo</em> tortoises, which live alone and do not engage in parental care. They found that tortoise hatchlings showed a significant preference for the image, suggesting that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"a3d70ab9-55c8-45a0-b449-faf85e46e246","content":"<p>face-like stimuli are likely perceived as harmless by newborns of social species that practice parental care but as threatening by newborns of solitary species without parental care.</p>"},{"id":"7d6148a7-2dac-408c-8e14-faf98ecfe09f","content":"<p>researchers should not assume that an innate attraction to face-like stimuli is necessarily an adaptation related to social interaction or parental care.</p>"},{"id":"12bb1709-583a-4015-a629-607ae5cb329b","content":"<p>researchers can assume that the attraction to face-like stimuli that is seen in social species that practice parental care is learned rather than innate.</p>"},{"id":"7e4ce1a3-bf8c-481a-8559-3c5423ccda85","content":"<p>newly hatched <em>Testudo&nbsp;</em>tortoises show a stronger preference for face-like stimuli than adult <em>Testudo&nbsp;</em>tortoises do.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["7d6148a7-2dac-408c-8e14-faf98ecfe09f"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of the study by Versace and colleagues. The text indicates that newborn animals of some species are attracted to faces and to stimuli that resemble faces. These species, the text says, share two characteristics: they&rsquo;re social and they practice parental care, meaning that parents care for their young. The text goes on to describe Versace and colleagues&rsquo; experiment, which showed that <em>Testudo</em> tortoises, which aren&rsquo;t social and don&rsquo;t practice parental care, were attracted to a stimulus that resembles a face. Since Versace and colleagues have shown that a species that isn&rsquo;t social and doesn&rsquo;t practice parental care nevertheless has the innate characteristic of being attracted to face-like stimuli, it follows that this characteristic shouldn&rsquo;t be assumed to be an adaptation related to social interaction or parental care. </p><p>Choice A is incorrect because the text indicates that the tortoise hatchlings, which are solitary and don&rsquo;t practice parental care, were attracted to the face-like stimuli, not that they perceived the stimuli as threatening. Choice C is incorrect because the phenomenon discussed in the text is an attraction to faces and face-like stimuli on the part of newborn animals, which can&rsquo;t show any learned characteristics since they were just born. Additionally, the text tells us that the tortoises Versace and colleagues studied aren&rsquo;t social and don&rsquo;t practice parental care, so any findings about those tortoises wouldn&rsquo;t be relevant to the question of whether an attraction to faces in social species that practice parental care is innate or learned.&nbsp;Choice D is incorrect because the text gives no indication that adult tortoises were tested on face-like stimuli and, if adults were in fact tested, no information about how they responded is provided. Since no information about adult tortoises&rsquo; responses is provided, no conclusion comparing those responses to the responses of newly hatched tortoises can be supported. </p>$SATQ$, false, 0, $SATQ$OSP-010-INF$SATQ$, $SATQ$$SATQ$, $SATQ$5af87a70-0757-48e7-89df-ed1206652dfb$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f2250478","external_id":"1830f378-1723-46f1-b0c3-3f7fd3b742f3","vaultid":"eff482f7-c758-42d8-9917-829c9da9b005","uId":"b0cc0474-4e3f-45fc-8c15-d17501110d32","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Among social animals that care for their young, such as chickens, macaque monkeys, and humans, newborns appear to show an innate attraction to faces and face-like stimuli. Elisabetta Versace and her colleagues used an image of three black dots arranged in the shape of eyes and a nose or mouth to test whether this trait also occurs in <em>Testudo</em> tortoises, which live alone and do not engage in parental care. They found that tortoise hatchlings showed a significant preference for the image, suggesting that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"a3d70ab9-55c8-45a0-b449-faf85e46e246","content":"<p>face-like stimuli are likely perceived as harmless by newborns of social species that practice parental care but as threatening by newborns of solitary species without parental care.</p>"},{"id":"7d6148a7-2dac-408c-8e14-faf98ecfe09f","content":"<p>researchers should not assume that an innate attraction to face-like stimuli is necessarily an adaptation related to social interaction or parental care.</p>"},{"id":"12bb1709-583a-4015-a629-607ae5cb329b","content":"<p>researchers can assume that the attraction to face-like stimuli that is seen in social species that practice parental care is learned rather than innate.</p>"},{"id":"7e4ce1a3-bf8c-481a-8559-3c5423ccda85","content":"<p>newly hatched <em>Testudo&nbsp;</em>tortoises show a stronger preference for face-like stimuli than adult <em>Testudo&nbsp;</em>tortoises do.&nbsp;</p>"}],"keys":["7d6148a7-2dac-408c-8e14-faf98ecfe09f"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of the study by Versace and colleagues. The text indicates that newborn animals of some species are attracted to faces and to stimuli that resemble faces. These species, the text says, share two characteristics: they&rsquo;re social and they practice parental care, meaning that parents care for their young. The text goes on to describe Versace and colleagues&rsquo; experiment, which showed that <em>Testudo</em> tortoises, which aren&rsquo;t social and don&rsquo;t practice parental care, were attracted to a stimulus that resembles a face. Since Versace and colleagues have shown that a species that isn&rsquo;t social and doesn&rsquo;t practice parental care nevertheless has the innate characteristic of being attracted to face-like stimuli, it follows that this characteristic shouldn&rsquo;t be assumed to be an adaptation related to social interaction or parental care. </p><p>Choice A is incorrect because the text indicates that the tortoise hatchlings, which are solitary and don&rsquo;t practice parental care, were attracted to the face-like stimuli, not that they perceived the stimuli as threatening. Choice C is incorrect because the phenomenon discussed in the text is an attraction to faces and face-like stimuli on the part of newborn animals, which can&rsquo;t show any learned characteristics since they were just born. Additionally, the text tells us that the tortoises Versace and colleagues studied aren&rsquo;t social and don&rsquo;t practice parental care, so any findings about those tortoises wouldn&rsquo;t be relevant to the question of whether an attraction to faces in social species that practice parental care is innate or learned.&nbsp;Choice D is incorrect because the text gives no indication that adult tortoises were tested on face-like stimuli and, if adults were in fact tested, no information about how they responded is provided. Since no information about adult tortoises&rsquo; responses is provided, no conclusion comparing those responses to the responses of newly hatched tortoises can be supported. </p>","parenttemplatename":"OSP-010-INF","parenttemplateid":"","templateclusterid":"5af87a70-0757-48e7-89df-ed1206652dfb","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959314,"updateDate":1691007959314}$SATQ$::jsonb, 1691007959314, 1691007959314),
    ($SATQ$f27559d4$SATQ$, $SATQ$08272652-dc6b-4cfa-a163-587bce316822$SATQ$::uuid, $SATQ$07ce1250-30ee-467a-a3e8-175731763dac$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Volunteering, or giving time for a community service for free, is a valuable form of civic engagement because helping in a community is also good for society as a whole. In a survey of youths in the United States, most young people said that they believe volunteering is a way to help people on an individual level. Meanwhile, only 6% of the youths said that they think volunteering is a way to help fix problems in society overall. These replies suggest that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"063aecd5-dea1-4a3c-bad1-1923064b5c18","content":"<p>many young people think they can volunteer only within their own communities.</p>"},{"id":"d090e9bb-712b-4764-9f67-8edac905bae7","content":"<p>volunteering may be even more helpful than many young people think it is.</p>"},{"id":"8056186f-d5e0-4477-b01f-530fb5d5d14b","content":"<p>volunteering can help society overall more than it can help individual people.</p>"},{"id":"b5e90463-6f45-4775-914b-0fb8489c43d8","content":"<p>many young people may not know how to find ways to volunteer their time.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["d090e9bb-712b-4764-9f67-8edac905bae7"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of volunteering. The text asserts that volunteering benefits both the community in which one volunteers and society as a whole. It then states that in a survey of young people, a majority of respondents said that volunteering helps individuals, but only 6% of respondents said that volunteering helps society as a whole. If volunteering does in fact help society as a whole, as the text says, but only 6% of young people believe it does, then it&rsquo;s reasonable to conclude that volunteering is more helpful than many young people think it is.&nbsp;</p><p>Choice A is incorrect because the text discusses young people&rsquo;s beliefs about the benefits of volunteering, not where young people believe they are able to volunteer. Nothing in the text suggests that many young people believe they are only able to volunteer in their own communities. Choice C is incorrect. Although the text indicates that volunteering is beneficial for society as a whole, nothing in the text suggests that volunteering can benefit society more than it can benefit individual people. The text doesn&rsquo;t compare the benefits to society with the benefits to individuals.&nbsp;Choice D is incorrect because the text discusses young people&rsquo;s beliefs about the benefits of volunteering, not how to find volunteering opportunities. There&rsquo;s nothing in the text to suggest that many young people don&rsquo;t know how to volunteer.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-032-INF$SATQ$, $SATQ$$SATQ$, $SATQ$2e9c25fd-c0f3-4cdd-a9b2-2854274f40a9$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f27559d4","external_id":"08272652-dc6b-4cfa-a163-587bce316822","vaultid":"07ce1250-30ee-467a-a3e8-175731763dac","uId":"ca699796-61e1-4cdc-92ef-5a82c1721a2b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Volunteering, or giving time for a community service for free, is a valuable form of civic engagement because helping in a community is also good for society as a whole. In a survey of youths in the United States, most young people said that they believe volunteering is a way to help people on an individual level. Meanwhile, only 6% of the youths said that they think volunteering is a way to help fix problems in society overall. These replies suggest that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"063aecd5-dea1-4a3c-bad1-1923064b5c18","content":"<p>many young people think they can volunteer only within their own communities.</p>"},{"id":"d090e9bb-712b-4764-9f67-8edac905bae7","content":"<p>volunteering may be even more helpful than many young people think it is.</p>"},{"id":"8056186f-d5e0-4477-b01f-530fb5d5d14b","content":"<p>volunteering can help society overall more than it can help individual people.</p>"},{"id":"b5e90463-6f45-4775-914b-0fb8489c43d8","content":"<p>many young people may not know how to find ways to volunteer their time.</p>"}],"keys":["d090e9bb-712b-4764-9f67-8edac905bae7"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of volunteering. The text asserts that volunteering benefits both the community in which one volunteers and society as a whole. It then states that in a survey of young people, a majority of respondents said that volunteering helps individuals, but only 6% of respondents said that volunteering helps society as a whole. If volunteering does in fact help society as a whole, as the text says, but only 6% of young people believe it does, then it&rsquo;s reasonable to conclude that volunteering is more helpful than many young people think it is.&nbsp;</p><p>Choice A is incorrect because the text discusses young people&rsquo;s beliefs about the benefits of volunteering, not where young people believe they are able to volunteer. Nothing in the text suggests that many young people believe they are only able to volunteer in their own communities. Choice C is incorrect. Although the text indicates that volunteering is beneficial for society as a whole, nothing in the text suggests that volunteering can benefit society more than it can benefit individual people. The text doesn&rsquo;t compare the benefits to society with the benefits to individuals.&nbsp;Choice D is incorrect because the text discusses young people&rsquo;s beliefs about the benefits of volunteering, not how to find volunteering opportunities. There&rsquo;s nothing in the text to suggest that many young people don&rsquo;t know how to volunteer.&nbsp;</p>","parenttemplatename":"OSP-032-INF","parenttemplateid":"","templateclusterid":"2e9c25fd-c0f3-4cdd-a9b2-2854274f40a9","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959319,"updateDate":1691007959319}$SATQ$::jsonb, 1691007959319, 1691007959319),
    ($SATQ$f2b3b53b$SATQ$, $SATQ$bce1433e-0679-4c4f-88e2-a37d1892537d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>External shopping cues are a type of marketing that uses obvious messaging&mdash;a display featuring a new product, for example, or a &ldquo;buy one, get one free&rdquo; offer&mdash;to entice consumers to make spontaneous purchases. In a study, data scientist Sam K. Hui and colleagues found that this effect can also be achieved with a less obvious cue: rearranging a store&rsquo;s layout. The researchers explain that trying to find items in new locations causes shoppers to move through more of the store, exposing them to more products and increasing the likelihood that they&rsquo;ll buy an item they hadn&rsquo;t planned on purchasing.</p>$SATQ$, $SATQ$<p>Which response from a survey given to shoppers who made a purchase at a retail store best supports the researchers&rsquo; explanation?</p>$SATQ$, $SATQ$[{"id":"ce90a07b-1224-4891-a9f2-a14d19ea658c","content":"<p>&ldquo;I needed to buy some cleaning supplies, but they weren&rsquo;t in their regular place. While I was looking for them, I saw this interesting notebook and decided to buy it, too.&rdquo;</p>"},{"id":"3120f5c4-0862-4865-8759-49fca8174462","content":"<p>&ldquo;I didn&rsquo;t buy everything on my shopping list today. I couldn&rsquo;t find a couple of the items in the store, even though I looked all over for them.&rdquo;</p>"},{"id":"25e6cc97-a235-4614-8d87-3e158b864114","content":"<p>&ldquo;The store sent me a coupon for a new brand of soup, so I came here to find out what kinds of soup that brand offers. I decided to buy a few cans because I had the coupon.&rdquo;</p>"},{"id":"b6ef25ba-4033-4da8-9cd7-38014736d19d","content":"<p>&ldquo;This store is larger than one that&rsquo;s closer to where I live, and it carries more products. I came here to buy some things that the other store doesn&rsquo;t always have.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["ce90a07b-1224-4891-a9f2-a14d19ea658c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it best supports the researchers&rsquo; explanation of the results of rearranging a store&rsquo;s layout. According to the text, Sam K. Hui and colleagues found that rearranging a store&rsquo;s layout can encourage customers to make spontaneous purchases. The text states that the researchers explain that a change in layout causes shoppers to hunt for items&rsquo; new locations, which exposes the shoppers to more products and increases the likelihood that they&rsquo;ll make an unplanned purchase. This quotation from a surveyed shopper indicates that the shopper spontaneously purchased a notebook while looking for cleaning supplies that weren&rsquo;t in their usual place. The quotation therefore supports the researchers&rsquo; explanation that rearranging a store&rsquo;s layout can lead shoppers to make unanticipated purchases.</p><p>Choice B is incorrect because it doesn&rsquo;t support the researchers&rsquo; explanation that rearranging a store&rsquo;s layout can lead shoppers to make unanticipated purchases. Instead of attributing an unplanned purchase to a change in layout, the quotation notes that the shopper searched for but couldn&rsquo;t find some items, and as a result the shopper purchased less, not more, than what was anticipated. Choice C is incorrect because the quotation attributes what was purchased to coupons that the shopper received, not to a new store layout. Thus, the quotation doesn&rsquo;t support the researchers&rsquo; explanation that rearranging a store&rsquo;s layout can lead shoppers to make unanticipated purchases. Choice D is incorrect because the quotation attributes what was purchased to the size and stock of the store, not to a new store layout. The shopper simply purchased products that the shopper wanted in a particular store because other stores didn&rsquo;t carry those products, so the quotation doesn&rsquo;t support the researchers&rsquo; explanation that rearranging a store&rsquo;s layout can lead shoppers to make spontaneous purchases.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f2b3b53b","external_id":"bce1433e-0679-4c4f-88e2-a37d1892537d","vaultid":null,"uId":"696a0fe6-b2be-4726-8612-7d477fb25265","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>External shopping cues are a type of marketing that uses obvious messaging&mdash;a display featuring a new product, for example, or a &ldquo;buy one, get one free&rdquo; offer&mdash;to entice consumers to make spontaneous purchases. In a study, data scientist Sam K. Hui and colleagues found that this effect can also be achieved with a less obvious cue: rearranging a store&rsquo;s layout. The researchers explain that trying to find items in new locations causes shoppers to move through more of the store, exposing them to more products and increasing the likelihood that they&rsquo;ll buy an item they hadn&rsquo;t planned on purchasing.</p>","stem":"<p>Which response from a survey given to shoppers who made a purchase at a retail store best supports the researchers&rsquo; explanation?</p>","answerOptions":[{"id":"ce90a07b-1224-4891-a9f2-a14d19ea658c","content":"<p>&ldquo;I needed to buy some cleaning supplies, but they weren&rsquo;t in their regular place. While I was looking for them, I saw this interesting notebook and decided to buy it, too.&rdquo;</p>"},{"id":"3120f5c4-0862-4865-8759-49fca8174462","content":"<p>&ldquo;I didn&rsquo;t buy everything on my shopping list today. I couldn&rsquo;t find a couple of the items in the store, even though I looked all over for them.&rdquo;</p>"},{"id":"25e6cc97-a235-4614-8d87-3e158b864114","content":"<p>&ldquo;The store sent me a coupon for a new brand of soup, so I came here to find out what kinds of soup that brand offers. I decided to buy a few cans because I had the coupon.&rdquo;</p>"},{"id":"b6ef25ba-4033-4da8-9cd7-38014736d19d","content":"<p>&ldquo;This store is larger than one that&rsquo;s closer to where I live, and it carries more products. I came here to buy some things that the other store doesn&rsquo;t always have.&rdquo;</p>"}],"keys":["ce90a07b-1224-4891-a9f2-a14d19ea658c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it best supports the researchers&rsquo; explanation of the results of rearranging a store&rsquo;s layout. According to the text, Sam K. Hui and colleagues found that rearranging a store&rsquo;s layout can encourage customers to make spontaneous purchases. The text states that the researchers explain that a change in layout causes shoppers to hunt for items&rsquo; new locations, which exposes the shoppers to more products and increases the likelihood that they&rsquo;ll make an unplanned purchase. This quotation from a surveyed shopper indicates that the shopper spontaneously purchased a notebook while looking for cleaning supplies that weren&rsquo;t in their usual place. The quotation therefore supports the researchers&rsquo; explanation that rearranging a store&rsquo;s layout can lead shoppers to make unanticipated purchases.</p><p>Choice B is incorrect because it doesn&rsquo;t support the researchers&rsquo; explanation that rearranging a store&rsquo;s layout can lead shoppers to make unanticipated purchases. Instead of attributing an unplanned purchase to a change in layout, the quotation notes that the shopper searched for but couldn&rsquo;t find some items, and as a result the shopper purchased less, not more, than what was anticipated. Choice C is incorrect because the quotation attributes what was purchased to coupons that the shopper received, not to a new store layout. Thus, the quotation doesn&rsquo;t support the researchers&rsquo; explanation that rearranging a store&rsquo;s layout can lead shoppers to make unanticipated purchases. Choice D is incorrect because the quotation attributes what was purchased to the size and stock of the store, not to a new store layout. The shopper simply purchased products that the shopper wanted in a particular store because other stores didn&rsquo;t carry those products, so the quotation doesn&rsquo;t support the researchers&rsquo; explanation that rearranging a store&rsquo;s layout can lead shoppers to make spontaneous purchases.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323045,"updateDate":1730147323045}$SATQ$::jsonb, 1730147323045, 1730147323045),
    ($SATQ$f38b40ac$SATQ$, $SATQ$ef9499bb-6d7f-4c00-a193-e4c998f973b6$SATQ$::uuid, $SATQ$31ef71f2-7096-4f55-9642-e5e0c1839de2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In addition to her technical skill and daring feats, American stunt pilot Bessie Coleman was also known for dazzling the crowds that came to watch her air shows in the 1920s with her exuberant personality. During her career, she was careful and purposeful about how she crafted her public persona. An aviation researcher has claimed that Coleman intentionally defied social norms of the time by how she chose to present herself to the public.</p>$SATQ$, $SATQ$<p>Which quotation from an article about Coleman would most directly support the aviation researcher&rsquo;s claim?</p>$SATQ$, $SATQ$[{"id":"3adfe93c-9187-468d-9b8b-09ed787e4e28","content":"<p>&ldquo;For her air shows, Coleman frequently used the Curtiss JN-4, or &lsquo;Jenny,&rsquo; which at that time was one of the most well-known types of planes.&rdquo;</p>"},{"id":"1ef379a1-8f36-4b0f-b82e-45370ae78b52","content":"<p>&ldquo;While Coleman was beloved by spectators for her charisma, she had a more complicated relationship with her managers and staff, who at times found her behavior too impulsive and demanding.&rdquo;</p>"},{"id":"52d53d7a-4061-4e3d-87b0-0df0990c8ddd","content":"<p>&ldquo;Coleman once considered leaving her career as a stunt pilot to focus her efforts on giving speeches, which she felt would better support her public image.&rdquo;&nbsp;</p>"},{"id":"49d3e4fe-d107-4851-84f0-e1c17cd0d5bc","content":"<p>&ldquo;Although female pilots were typically expected to wear traditional but impractical attire that included dresses or skirts, photographs of Coleman show her wearing pants and leather jackets.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["49d3e4fe-d107-4851-84f0-e1c17cd0d5bc"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. This choice supports the claim of Coleman&rsquo;s intentional defiance of social norms: female pilots were expected to wear skirts, but Coleman wore pants and leather jackets instead. </p><p>Choice A is incorrect. Coleman flew a well-known, common plane, which would not have defied social norms among pilots. Choice B is incorrect. Her complicated relationship with managers and staff would not have been a component of Coleman&rsquo;s public persona. This choice also fails to mention any &ldquo;social norms of the time.&rdquo; Choice C is incorrect. While this quotation suggests that Coleman was careful and purposeful about her public image, it doesn&rsquo;t directly mention anything about &ldquo;social norms of the time.&rdquo; </p>$SATQ$, false, 0, $SATQ$OSP-KA-TXT-M007$SATQ$, $SATQ$$SATQ$, $SATQ$74719f42-952c-4c7c-8878-e2b4ca637913$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f38b40ac","external_id":"ef9499bb-6d7f-4c00-a193-e4c998f973b6","vaultid":"31ef71f2-7096-4f55-9642-e5e0c1839de2","uId":"b5efd44a-16d8-4545-9a66-7a3eae5f9c5d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In addition to her technical skill and daring feats, American stunt pilot Bessie Coleman was also known for dazzling the crowds that came to watch her air shows in the 1920s with her exuberant personality. During her career, she was careful and purposeful about how she crafted her public persona. An aviation researcher has claimed that Coleman intentionally defied social norms of the time by how she chose to present herself to the public.</p>","stem":"<p>Which quotation from an article about Coleman would most directly support the aviation researcher&rsquo;s claim?</p>","answerOptions":[{"id":"3adfe93c-9187-468d-9b8b-09ed787e4e28","content":"<p>&ldquo;For her air shows, Coleman frequently used the Curtiss JN-4, or &lsquo;Jenny,&rsquo; which at that time was one of the most well-known types of planes.&rdquo;</p>"},{"id":"1ef379a1-8f36-4b0f-b82e-45370ae78b52","content":"<p>&ldquo;While Coleman was beloved by spectators for her charisma, she had a more complicated relationship with her managers and staff, who at times found her behavior too impulsive and demanding.&rdquo;</p>"},{"id":"52d53d7a-4061-4e3d-87b0-0df0990c8ddd","content":"<p>&ldquo;Coleman once considered leaving her career as a stunt pilot to focus her efforts on giving speeches, which she felt would better support her public image.&rdquo;&nbsp;</p>"},{"id":"49d3e4fe-d107-4851-84f0-e1c17cd0d5bc","content":"<p>&ldquo;Although female pilots were typically expected to wear traditional but impractical attire that included dresses or skirts, photographs of Coleman show her wearing pants and leather jackets.&rdquo;</p>"}],"keys":["49d3e4fe-d107-4851-84f0-e1c17cd0d5bc"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. This choice supports the claim of Coleman&rsquo;s intentional defiance of social norms: female pilots were expected to wear skirts, but Coleman wore pants and leather jackets instead. </p><p>Choice A is incorrect. Coleman flew a well-known, common plane, which would not have defied social norms among pilots. Choice B is incorrect. Her complicated relationship with managers and staff would not have been a component of Coleman&rsquo;s public persona. This choice also fails to mention any &ldquo;social norms of the time.&rdquo; Choice C is incorrect. While this quotation suggests that Coleman was careful and purposeful about her public image, it doesn&rsquo;t directly mention anything about &ldquo;social norms of the time.&rdquo; </p>","parenttemplatename":"OSP-KA-TXT-M007","parenttemplateid":"","templateclusterid":"74719f42-952c-4c7c-8878-e2b4ca637913","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959377,"updateDate":1691007959377}$SATQ$::jsonb, 1691007959377, 1691007959377),
    ($SATQ$f39507a3$SATQ$, $SATQ$03463f37-4904-4865-bb31-d326c1dd67e8$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>One challenge when researching whether holding elected office changes a person&rsquo;s behavior is the problem of ensuring that the experiment has an appropriate control group. To reveal the effect of holding office, researchers must compare people who hold elected office with people who do not hold office but who are otherwise similar to the office-holders. Since researchers are unable to control which politicians win elections, they therefore <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"5be07825-3cf9-4f32-aa38-0104ab567a44","content":"<p>struggle to find valid data about the behavior of politicians who do not currently hold office.</p>"},{"id":"36e6e87d-1b5c-4dcf-bf57-8e8f2c08d227","content":"<p>can only conduct valid studies with people who have previously held office rather than people who presently hold office.</p>"},{"id":"ed3e6f0a-9a94-4193-8f7d-62db753501f4","content":"<p>should select a control group of people who differ from office-holders in several significant ways.</p>"},{"id":"25b7d550-413d-48d9-ace1-b8ede9eb120f","content":"<p>will find it difficult to identify a group of people who can function as an appropriate control group for their studies.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["25b7d550-413d-48d9-ace1-b8ede9eb120f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of the challenge researchers face when studying the effects of holding elected office on a person&rsquo;s behavior. The text explains that it&rsquo;s hard for researchers to test for the effects that elected office has on people because finding people to serve as a control group is difficult. The text indicates that a control group needs to be made up of people who share characteristics of the group being tested but don&rsquo;t have the variable being tested (in this case, holding elected office). Because researchers aren&rsquo;t able to influence who wins elections, they&rsquo;re also unable to determine who would serve as an appropriately similar member of a control group. Thus, it logically follows that researchers will find it difficult to identify a group of people who can function as an appropriate control group for their studies.</p><p>Choice A is incorrect because the text focuses on the struggle to put together a control group for experiments; it doesn&rsquo;t suggest that finding information about politicians&rsquo; behavior is difficult. Choice B is incorrect because the experiments mentioned in the text are testing the effects of holding elected office on a person&rsquo;s behavior. Studying people who have already held elected office wouldn&rsquo;t provide an opportunity to note any behavioral changes that the position might cause. Choice C is incorrect because the text defines people in a control group as those "who are otherwise similar to the office-holders"; selecting people who differ from the office-holders wouldn&rsquo;t fit the criteria for an appropriate control group.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f39507a3","external_id":"03463f37-4904-4865-bb31-d326c1dd67e8","vaultid":null,"uId":"34465990-18ed-445b-b5f3-0faf6599ed0d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>One challenge when researching whether holding elected office changes a person&rsquo;s behavior is the problem of ensuring that the experiment has an appropriate control group. To reveal the effect of holding office, researchers must compare people who hold elected office with people who do not hold office but who are otherwise similar to the office-holders. Since researchers are unable to control which politicians win elections, they therefore <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"5be07825-3cf9-4f32-aa38-0104ab567a44","content":"<p>struggle to find valid data about the behavior of politicians who do not currently hold office.</p>"},{"id":"36e6e87d-1b5c-4dcf-bf57-8e8f2c08d227","content":"<p>can only conduct valid studies with people who have previously held office rather than people who presently hold office.</p>"},{"id":"ed3e6f0a-9a94-4193-8f7d-62db753501f4","content":"<p>should select a control group of people who differ from office-holders in several significant ways.</p>"},{"id":"25b7d550-413d-48d9-ace1-b8ede9eb120f","content":"<p>will find it difficult to identify a group of people who can function as an appropriate control group for their studies.</p>"}],"keys":["25b7d550-413d-48d9-ace1-b8ede9eb120f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of the challenge researchers face when studying the effects of holding elected office on a person&rsquo;s behavior. The text explains that it&rsquo;s hard for researchers to test for the effects that elected office has on people because finding people to serve as a control group is difficult. The text indicates that a control group needs to be made up of people who share characteristics of the group being tested but don&rsquo;t have the variable being tested (in this case, holding elected office). Because researchers aren&rsquo;t able to influence who wins elections, they&rsquo;re also unable to determine who would serve as an appropriately similar member of a control group. Thus, it logically follows that researchers will find it difficult to identify a group of people who can function as an appropriate control group for their studies.</p><p>Choice A is incorrect because the text focuses on the struggle to put together a control group for experiments; it doesn&rsquo;t suggest that finding information about politicians&rsquo; behavior is difficult. Choice B is incorrect because the experiments mentioned in the text are testing the effects of holding elected office on a person&rsquo;s behavior. Studying people who have already held elected office wouldn&rsquo;t provide an opportunity to note any behavioral changes that the position might cause. Choice C is incorrect because the text defines people in a control group as those \"who are otherwise similar to the office-holders\"; selecting people who differ from the office-holders wouldn&rsquo;t fit the criteria for an appropriate control group.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1691007959314,"updateDate":1691007959314}$SATQ$::jsonb, 1691007959314, 1691007959314),
    ($SATQ$f3f444bc$SATQ$, $SATQ$51cf5c80-7d35-47f7-992c-19426432b1a4$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Many mosquito repellents contain natural components that work by activating multiple odor receptors on mosquitoes&rsquo; antennae. As the insects develop resistance, new repellents are needed. Ke Dong and her team found that EBF, a molecular component of a chrysanthemum-flower extract, can repel mosquitoes by activating just one odor receptor&mdash;and this receptor, <span data-ssml-say-as="characters">Or31</span>, is present in all mosquito species known to carry diseases. Therefore, the researchers suggest that in developing new repellents, it would be most useful to <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"4a872720-75e8-4adc-a88a-743996330104","content":"<p>identify molecular components similar to EBF that target the activation of <span data-ssml-say-as=\"characters\">Or31</span> receptors.</p>"},{"id":"b1ed6fea-d033-430b-b99f-9335bd27f383","content":"<p>investigate alternative methods for extracting EBF molecules from chrysanthemums.</p>"},{"id":"003e001e-7fc1-470c-9762-f04588d6bafd","content":"<p>verify the precise locations of <span data-ssml-say-as=\"characters\">Or31</span> and other odor receptors on mosquitoes&rsquo; antennae.</p>"},{"id":"4b014cd1-5025-4725-8f8a-520f68218ede","content":"<p>determine the maximum number of different odor receptors that can be activated by a single molecule.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["4a872720-75e8-4adc-a88a-743996330104"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of mosquito repellents. The text begins by explaining that many repellents work by using natural components to activate multiple odor receptors on mosquitoes&rsquo; antennae, and that new repellents must be created whenever mosquitoes become resistant to older ones. The text then highlights a research team&rsquo;s discovery that EBF, a molecular component of a chrysanthemum-flower extract, can repel mosquitoes by activating a single odor receptor, Or31, that is shared by all species of mosquitoes known to carry diseases. The text suggests that compared to the repellents mentioned earlier, a repellent that acts on the Or31 receptor would be more effective: by noting that all mosquito species known to carry diseases share the Or31 receptor, the text suggests that the Or31 receptor may be unique in this respect, meaning that a repellent such as EBF that acts on it would be more effective since it works on a single receptor shared by all mosquito species that carry diseases, rather than a combination of receptors that is not shared by all species. Once mosquitoes become resistant to EBF, it would therefore make sense for researchers to look for other molecular components similar to EBF that target the activation of Or31 receptors, since a single such component could also repel all disease-carrying mosquitoes.</p><p>Choice B is incorrect because nothing in the text suggests that EBF molecules are difficult to extract from chrysanthemums and that investigating alternative extraction methods would therefore be useful for developing efficient and effective mosquito repellents. Rather, the text suggests that researchers developing new mosquito repellents should aim to identify molecular components similar to EBF, since that component targets the Or31 odor receptor shared by all species of mosquitoes known to carry diseases. Choice C is incorrect because nothing in the text suggests that researchers are unaware of the precise location of Or31 and other odor receptors in mosquitoes&rsquo; antennae or that knowing this information would be useful for developing efficient and effective mosquito repellents. Rather, the text suggests that researchers developing new mosquito repellents should aim to identify molecular components similar to EBF, which targets the Or31 odor receptor. Choice D is incorrect because it doesn&rsquo;t logically follow that the discovery of one odor receptor shared by all disease-bearing mosquitoes should lead to further research into which repellents might activate the greatest number of odor receptors. Rather, the text suggests that researchers developing new mosquito repellents should instead search for additional molecular components that, like EBF, activate the one odor receptor that is known to be shared by all disease-bearing mosquitoes.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f3f444bc","external_id":"51cf5c80-7d35-47f7-992c-19426432b1a4","vaultid":null,"uId":"bec2f795-1d97-45c8-909d-1042527f51d6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Many mosquito repellents contain natural components that work by activating multiple odor receptors on mosquitoes&rsquo; antennae. As the insects develop resistance, new repellents are needed. Ke Dong and her team found that EBF, a molecular component of a chrysanthemum-flower extract, can repel mosquitoes by activating just one odor receptor&mdash;and this receptor, <span data-ssml-say-as=\"characters\">Or31</span>, is present in all mosquito species known to carry diseases. Therefore, the researchers suggest that in developing new repellents, it would be most useful to <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"4a872720-75e8-4adc-a88a-743996330104","content":"<p>identify molecular components similar to EBF that target the activation of <span data-ssml-say-as=\"characters\">Or31</span> receptors.</p>"},{"id":"b1ed6fea-d033-430b-b99f-9335bd27f383","content":"<p>investigate alternative methods for extracting EBF molecules from chrysanthemums.</p>"},{"id":"003e001e-7fc1-470c-9762-f04588d6bafd","content":"<p>verify the precise locations of <span data-ssml-say-as=\"characters\">Or31</span> and other odor receptors on mosquitoes&rsquo; antennae.</p>"},{"id":"4b014cd1-5025-4725-8f8a-520f68218ede","content":"<p>determine the maximum number of different odor receptors that can be activated by a single molecule.</p>"}],"keys":["4a872720-75e8-4adc-a88a-743996330104"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of mosquito repellents. The text begins by explaining that many repellents work by using natural components to activate multiple odor receptors on mosquitoes&rsquo; antennae, and that new repellents must be created whenever mosquitoes become resistant to older ones. The text then highlights a research team&rsquo;s discovery that EBF, a molecular component of a chrysanthemum-flower extract, can repel mosquitoes by activating a single odor receptor, Or31, that is shared by all species of mosquitoes known to carry diseases. The text suggests that compared to the repellents mentioned earlier, a repellent that acts on the Or31 receptor would be more effective: by noting that all mosquito species known to carry diseases share the Or31 receptor, the text suggests that the Or31 receptor may be unique in this respect, meaning that a repellent such as EBF that acts on it would be more effective since it works on a single receptor shared by all mosquito species that carry diseases, rather than a combination of receptors that is not shared by all species. Once mosquitoes become resistant to EBF, it would therefore make sense for researchers to look for other molecular components similar to EBF that target the activation of Or31 receptors, since a single such component could also repel all disease-carrying mosquitoes.</p><p>Choice B is incorrect because nothing in the text suggests that EBF molecules are difficult to extract from chrysanthemums and that investigating alternative extraction methods would therefore be useful for developing efficient and effective mosquito repellents. Rather, the text suggests that researchers developing new mosquito repellents should aim to identify molecular components similar to EBF, since that component targets the Or31 odor receptor shared by all species of mosquitoes known to carry diseases. Choice C is incorrect because nothing in the text suggests that researchers are unaware of the precise location of Or31 and other odor receptors in mosquitoes&rsquo; antennae or that knowing this information would be useful for developing efficient and effective mosquito repellents. Rather, the text suggests that researchers developing new mosquito repellents should aim to identify molecular components similar to EBF, which targets the Or31 odor receptor. Choice D is incorrect because it doesn&rsquo;t logically follow that the discovery of one odor receptor shared by all disease-bearing mosquitoes should lead to further research into which repellents might activate the greatest number of odor receptors. Rather, the text suggests that researchers developing new mosquito repellents should instead search for additional molecular components that, like EBF, activate the one odor receptor that is known to be shared by all disease-bearing mosquitoes.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1691007959316,"updateDate":1691007959316}$SATQ$::jsonb, 1691007959316, 1691007959316),
    ($SATQ$f452410b$SATQ$, $SATQ$3b249e65-a66a-456e-8e49-c4382ffdef99$SATQ$::uuid, $SATQ$9b8579c1-2ba0-45a4-bb2f-bd97e8091b45$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Results of Footprint Analysis for Two Sets of Theropod Tracks</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Tracks</th><th scope="col" style="text-align: center;vertical-align: bottom;">Estimated footprint length (centimeters)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Average stride length (meters)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Estimated mean speed (meters per second)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">La Torre 6A</th><td style="text-align: center;">32.8</td><td style="text-align: center;">5.23</td><td style="text-align: center;">6.5&ndash;10.3</td></tr><tr><th scope="row" style="text-align: left;">La Torre 6B</th><td style="text-align: center;">28.9</td><td style="text-align: center;">5.57</td><td style="text-align: center;">8.8&ndash;12.4</td></tr></tbody></table></figure></p>
<p>The table shows data from paleontologist Ang&eacute;lica Torices and colleagues&rsquo; 2021 study of two sets of dinosaur tracks preserved in a fossilized lake bed in Spain. The tracks, referred to as La Torre 6A and La Torre 6B, were left by two individual theropods (dinosaurs that walked on two legs). The team&rsquo;s findings suggest that of the two theropods, the one that left the La Torre 6B tracks had a higher maximum mean speed, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the claim?</p>$SATQ$, $SATQ$[{"id":"422771f7-5834-406b-b554-719c3738f274","content":"<p>a longer footprint, and a longer average stride.</p>"},{"id":"80d82833-2a96-40e0-8968-53bb7ab9847c","content":"<p>a longer footprint, and a shorter average stride.</p>"},{"id":"014dc337-62f9-44f9-8487-1d9511b1020c","content":"<p>a shorter footprint, and a longer average stride.</p>"},{"id":"61e92a92-10b1-418f-82a6-0f765583876f","content":"<p>a shorter footprint, and a shorter average stride.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["014dc337-62f9-44f9-8487-1d9511b1020c"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most effectively uses data from the table to complete the claim about the tracks left by two therapods. The table indicates that the set of tracks labeled La Torre 6A has an estimated footprint length of 32.8 centimeters, an average stride length of 5.23 meters, and an estimated mean speed of 6.5&ndash;10.3 meters per second. For the set of tracks labeled La Torre 6B, on the other hand, the estimated footprint length is 28.9 centimeters, the average stride length is 5.57 meters, and the estimated mean speed is 8.8&ndash;12.4 meters per second. Therefore, the therapod that left the La Torre 6B tracks had a shorter footprint and a longer average stride than the one that left the La Torre 6A tracks.</p><p>Choice A is incorrect. While it is true that of the two therapods, the one that left the La Torre 6B tracks had a longer average stride, it didn&rsquo;t have a longer footprint: the table shows that its estimated footprint length is 28.9 centimeters, while La Torre 6A&rsquo;s estimated footprint length is 32.8 centimeters. Choice B is incorrect because the table shows that of the two therapods, the one that left the La Torre 6B tracks had a footprint length estimated at 28.9 centimeters, which is shorter than the 32.8 centimeters estimated for the other set of tracks. Moreover, the therapod that left the La Torre 6B tracks had a longer average stride, not shorter: 5.57 meters, compared with 5.23 meters for the other set of tracks. Choice D is incorrect. While it is true that of the two therapods, the one that left the La Torre 6B tracks had a shorter footprint, it didn&rsquo;t have a shorter average stride: the table shows that its average stride length is 5.57 meters, while La Torre 6A&rsquo;s average stride length is 5.23 meters.</p>$SATQ$, false, 0, $SATQ$OSP-533-QUA$SATQ$, $SATQ$$SATQ$, $SATQ$cf0e6ae1-aa99-4468-b3a5-e086faa0c4bf$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f452410b","external_id":"3b249e65-a66a-456e-8e49-c4382ffdef99","vaultid":"9b8579c1-2ba0-45a4-bb2f-bd97e8091b45","uId":"2f1fcab1-3c38-4ad7-9f9a-223d9ef29563","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Results of Footprint Analysis for Two Sets of Theropod Tracks</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Tracks</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Estimated footprint length (centimeters)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Average stride length (meters)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Estimated mean speed (meters per second)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">La Torre 6A</th><td style=\"text-align: center;\">32.8</td><td style=\"text-align: center;\">5.23</td><td style=\"text-align: center;\">6.5&ndash;10.3</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">La Torre 6B</th><td style=\"text-align: center;\">28.9</td><td style=\"text-align: center;\">5.57</td><td style=\"text-align: center;\">8.8&ndash;12.4</td></tr></tbody></table></figure></p>\n<p>The table shows data from paleontologist Ang&eacute;lica Torices and colleagues&rsquo; 2021 study of two sets of dinosaur tracks preserved in a fossilized lake bed in Spain. The tracks, referred to as La Torre 6A and La Torre 6B, were left by two individual theropods (dinosaurs that walked on two legs). The team&rsquo;s findings suggest that of the two theropods, the one that left the La Torre 6B tracks had a higher maximum mean speed, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the claim?</p>","answerOptions":[{"id":"422771f7-5834-406b-b554-719c3738f274","content":"<p>a longer footprint, and a longer average stride.</p>"},{"id":"80d82833-2a96-40e0-8968-53bb7ab9847c","content":"<p>a longer footprint, and a shorter average stride.</p>"},{"id":"014dc337-62f9-44f9-8487-1d9511b1020c","content":"<p>a shorter footprint, and a longer average stride.</p>"},{"id":"61e92a92-10b1-418f-82a6-0f765583876f","content":"<p>a shorter footprint, and a shorter average stride.</p>"}],"keys":["014dc337-62f9-44f9-8487-1d9511b1020c"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most effectively uses data from the table to complete the claim about the tracks left by two therapods. The table indicates that the set of tracks labeled La Torre 6A has an estimated footprint length of 32.8 centimeters, an average stride length of 5.23 meters, and an estimated mean speed of 6.5&ndash;10.3 meters per second. For the set of tracks labeled La Torre 6B, on the other hand, the estimated footprint length is 28.9 centimeters, the average stride length is 5.57 meters, and the estimated mean speed is 8.8&ndash;12.4 meters per second. Therefore, the therapod that left the La Torre 6B tracks had a shorter footprint and a longer average stride than the one that left the La Torre 6A tracks.</p><p>Choice A is incorrect. While it is true that of the two therapods, the one that left the La Torre 6B tracks had a longer average stride, it didn&rsquo;t have a longer footprint: the table shows that its estimated footprint length is 28.9 centimeters, while La Torre 6A&rsquo;s estimated footprint length is 32.8 centimeters. Choice B is incorrect because the table shows that of the two therapods, the one that left the La Torre 6B tracks had a footprint length estimated at 28.9 centimeters, which is shorter than the 32.8 centimeters estimated for the other set of tracks. Moreover, the therapod that left the La Torre 6B tracks had a longer average stride, not shorter: 5.57 meters, compared with 5.23 meters for the other set of tracks. Choice D is incorrect. While it is true that of the two therapods, the one that left the La Torre 6B tracks had a shorter footprint, it didn&rsquo;t have a shorter average stride: the table shows that its average stride length is 5.57 meters, while La Torre 6A&rsquo;s average stride length is 5.23 meters.</p>","parenttemplatename":"OSP-533-QUA","parenttemplateid":"","templateclusterid":"cf0e6ae1-aa99-4468-b3a5-e086faa0c4bf","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959338,"updateDate":1691007959338}$SATQ$::jsonb, 1691007959338, 1691007959338),
    ($SATQ$f495b554$SATQ$, $SATQ$e8b6d085-9a68-4f77-b022-fb65b1b3810c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Silicon-based photovoltaic cells account for 95% of the cells used in solar panels worldwide despite converting an average of only 18&ndash;22% of the sunlight that reaches them. In a study addressing this relative inefficiency, a team led by Laura Miranda-P&eacute;rez demonstrated that the addition of a thin layer of the mineral perovskite&mdash;which captures the blue range of light in the solar spectrum, whereas silicon captures the red range&mdash;allows the cells to convert 29.5% or more of the Sun&rsquo;s energy into usable electricity. Cells made with only perovskite, however, are no more efficient than silicon-based ones. It&rsquo;s reasonable to conclude, then, that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"6a633a25-d834-44d0-9de3-da2e795d6c68","content":"<p>photovoltaic cells with both silicon and perovskite are more efficient because they make use of more of the solar spectrum.&nbsp;</p>"},{"id":"8f9fc9bd-9d50-4ab0-8af5-34b43c440a8b","content":"<p>photovoltaic cells with only perovskite and no silicon would likely convert more than 29.5% of the Sun&rsquo;s energy.</p>"},{"id":"865cfec5-c900-480f-8069-bc217884b57e","content":"<p>solar power will remain elusive until photovoltaic cells are replaced with a more practical technology.&nbsp;</p>"},{"id":"db5db7b4-6bcd-4ede-9c87-45f07cdc65f5","content":"<p>researchers need to evaluate whether other minerals like perovskite are as effective as perovskite seems to be.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["6a633a25-d834-44d0-9de3-da2e795d6c68"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents the conclusion that most logically completes the text&rsquo;s discussion of the efficiency of various photovoltaic cells. The text indicates that Miranda-P&eacute;rez and her team found that adding a layer of perovskite to silicon-based cells increased the percentage of sunlight converted to usable electricity relative to the percentage converted to electricity by silicon-based cells. Using cells with only perovskite and no silicon, however, resulted in no improvement in efficiency over silicon-based cells. The text also states that perovskite captures light in the blue range of the solar spectrum and silicon captures light in the red range of the spectrum. If perovskite and silicon capture different parts of the solar spectrum and the combination of perovskite and silicon results in greater efficiency than the use of either perovskite or silicon alone does, then it is reasonable to infer that the improved efficiency of perovskite-silicon cells could be attributable to their making use of more of the solar spectrum than perovskite-based or silicon-based cells do.</p><p>Choice B is incorrect because it is directly contradicted by the text, which says that silicon-based cells convert 18%&ndash;22% of the sunlight that reaches them to electricity and that cells with only perovskite are no more efficient than silicon-based cells are. Perovskite-only cells thus must convert 22% or less&mdash;not more than 29.5%&mdash;of the sunlight that reaches them to electricity. Choice C is incorrect because the text focuses on a possible improvement to photovoltaic cells and makes no mention of any alternatives to those cells, so there is no reason to conclude that photovoltaic cells must be replaced with some other technology. Additionally, the text presents solar power as something that currently exists, so it wouldn&rsquo;t make sense to conclude that solar power will remain elusive. Choice D is incorrect because nothing in the text suggests that there is a need to evaluate the effectiveness of other minerals than perovskite. In fact, the text gives no indication that it is even possible to use other minerals than silicon and perovskite in photovoltaic cells. Instead, the text is focused on the effect of combining perovskite and silicon and the different parts of the solar spectrum that perovskite and silicon capture.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f495b554","external_id":"e8b6d085-9a68-4f77-b022-fb65b1b3810c","vaultid":null,"uId":"c206e268-b53b-422a-abe0-527413398e27","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Silicon-based photovoltaic cells account for 95% of the cells used in solar panels worldwide despite converting an average of only 18&ndash;22% of the sunlight that reaches them. In a study addressing this relative inefficiency, a team led by Laura Miranda-P&eacute;rez demonstrated that the addition of a thin layer of the mineral perovskite&mdash;which captures the blue range of light in the solar spectrum, whereas silicon captures the red range&mdash;allows the cells to convert 29.5% or more of the Sun&rsquo;s energy into usable electricity. Cells made with only perovskite, however, are no more efficient than silicon-based ones. It&rsquo;s reasonable to conclude, then, that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"6a633a25-d834-44d0-9de3-da2e795d6c68","content":"<p>photovoltaic cells with both silicon and perovskite are more efficient because they make use of more of the solar spectrum.&nbsp;</p>"},{"id":"8f9fc9bd-9d50-4ab0-8af5-34b43c440a8b","content":"<p>photovoltaic cells with only perovskite and no silicon would likely convert more than 29.5% of the Sun&rsquo;s energy.</p>"},{"id":"865cfec5-c900-480f-8069-bc217884b57e","content":"<p>solar power will remain elusive until photovoltaic cells are replaced with a more practical technology.&nbsp;</p>"},{"id":"db5db7b4-6bcd-4ede-9c87-45f07cdc65f5","content":"<p>researchers need to evaluate whether other minerals like perovskite are as effective as perovskite seems to be.</p>"}],"keys":["6a633a25-d834-44d0-9de3-da2e795d6c68"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents the conclusion that most logically completes the text&rsquo;s discussion of the efficiency of various photovoltaic cells. The text indicates that Miranda-P&eacute;rez and her team found that adding a layer of perovskite to silicon-based cells increased the percentage of sunlight converted to usable electricity relative to the percentage converted to electricity by silicon-based cells. Using cells with only perovskite and no silicon, however, resulted in no improvement in efficiency over silicon-based cells. The text also states that perovskite captures light in the blue range of the solar spectrum and silicon captures light in the red range of the spectrum. If perovskite and silicon capture different parts of the solar spectrum and the combination of perovskite and silicon results in greater efficiency than the use of either perovskite or silicon alone does, then it is reasonable to infer that the improved efficiency of perovskite-silicon cells could be attributable to their making use of more of the solar spectrum than perovskite-based or silicon-based cells do.</p><p>Choice B is incorrect because it is directly contradicted by the text, which says that silicon-based cells convert 18%&ndash;22% of the sunlight that reaches them to electricity and that cells with only perovskite are no more efficient than silicon-based cells are. Perovskite-only cells thus must convert 22% or less&mdash;not more than 29.5%&mdash;of the sunlight that reaches them to electricity. Choice C is incorrect because the text focuses on a possible improvement to photovoltaic cells and makes no mention of any alternatives to those cells, so there is no reason to conclude that photovoltaic cells must be replaced with some other technology. Additionally, the text presents solar power as something that currently exists, so it wouldn&rsquo;t make sense to conclude that solar power will remain elusive. Choice D is incorrect because nothing in the text suggests that there is a need to evaluate the effectiveness of other minerals than perovskite. In fact, the text gives no indication that it is even possible to use other minerals than silicon and perovskite in photovoltaic cells. Instead, the text is focused on the effect of combining perovskite and silicon and the different parts of the solar spectrum that perovskite and silicon capture.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323034,"updateDate":1730147323034}$SATQ$::jsonb, 1730147323034, 1730147323034),
    ($SATQ$f64ff4fb$SATQ$, $SATQ$0597edea-9496-40db-983f-e9f02858badc$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>In her 1998 book <em>Blues Legacies and Black Feminism</em>, Angela Y. Davis bases her analysis in part on recordings of songs sung in the 1920s by Gertrude &ldquo;Ma&rdquo; Rainey and Bessie Smith. Davis focuses on how Rainey and Smith improvised the lyrics&mdash;replacing the original lines with mischievous jokes and wordplay. Davis&rsquo;s work was particularly labor intensive because in order to transcribe, or write down, the lyrics as Rainey and Smith sang them, Davis had to listen repeatedly to the vinyl recordings, which weren&rsquo;t very clear.&nbsp;</p>$SATQ$, $SATQ$<p>What does the text most strongly suggest about the songs sung by Rainey and Smith?</p>$SATQ$, $SATQ$[{"id":"89a6ef0a-9a49-4d84-b782-f342384e1825","content":"<p>The songs have grown in popularity since Rainey and Smith first sang them.&nbsp;</p>"},{"id":"32e5623d-fb25-43fd-a86c-c77bde5a01ae","content":"<p>There were more recordings made of Rainey&rsquo;s songs than there were of Smith&rsquo;s.</p>"},{"id":"766432a0-203e-4196-a836-8b2ed7ce85c4","content":"<p>There were few, if any, reliable transcriptions of Smith&rsquo;s and Rainey&rsquo;s improvised lyrics when Davis began her research.</p>"},{"id":"ced48b1d-8290-4dd8-89a8-675b567732ee","content":"<p>According to Davis, the songs sung by Rainey were more musically innovative than those sung by Smith typically were.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["766432a0-203e-4196-a836-8b2ed7ce85c4"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it describes the songs sung by Gertrude "Ma" Rainey and Bessie Smith in a way the text implies is accurate. The text describes Angela Y. Davis&rsquo;s research on Rainey and Smith for her book <em>Blues Legacies and Black Feminism</em>, focusing on her efforts to transcribe the improvised lyrics in Rainey&rsquo;s and Smith&rsquo;s songs. The text calls Davis&rsquo;s transcription process "labor intensive" since the lack of clarity in the recordings required her to listen to each repeatedly to verify the accuracy of her transcripts. The fact that Davis undertook a painstaking transcription process using only fairly low-fidelity recordings suggests that reliable transcriptions were otherwise unavailable to her.</p><p>Choice A is incorrect. The text doesn&rsquo;t discuss the popularity of Rainey&rsquo;s and Smith&rsquo;s songs either in the 1920s or after. Although it is plausible that the music of Rainey and Smith is more widely enjoyed than it was in the 1920s, this isn&rsquo;t supported by the text. Choice B is incorrect. The text doesn&rsquo;t discuss which of Rainey and Smith was the more prolific recording artist and so provides no support for such a claim. Choice D is incorrect. The text discusses the creativity of both Rainey and Smith, but it does so only to note similarities between them in terms of improvisation and wit, not to emphasize differences between them or Davis&rsquo;s relative views of the artists&rsquo; inventiveness.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f64ff4fb","external_id":"0597edea-9496-40db-983f-e9f02858badc","vaultid":null,"uId":"f2ec59b8-910b-4b7a-a2a6-b28d11e77b6b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>In her 1998 book <em>Blues Legacies and Black Feminism</em>, Angela Y. Davis bases her analysis in part on recordings of songs sung in the 1920s by Gertrude &ldquo;Ma&rdquo; Rainey and Bessie Smith. Davis focuses on how Rainey and Smith improvised the lyrics&mdash;replacing the original lines with mischievous jokes and wordplay. Davis&rsquo;s work was particularly labor intensive because in order to transcribe, or write down, the lyrics as Rainey and Smith sang them, Davis had to listen repeatedly to the vinyl recordings, which weren&rsquo;t very clear.&nbsp;</p>","stem":"<p>What does the text most strongly suggest about the songs sung by Rainey and Smith?</p>","answerOptions":[{"id":"89a6ef0a-9a49-4d84-b782-f342384e1825","content":"<p>The songs have grown in popularity since Rainey and Smith first sang them.&nbsp;</p>"},{"id":"32e5623d-fb25-43fd-a86c-c77bde5a01ae","content":"<p>There were more recordings made of Rainey&rsquo;s songs than there were of Smith&rsquo;s.</p>"},{"id":"766432a0-203e-4196-a836-8b2ed7ce85c4","content":"<p>There were few, if any, reliable transcriptions of Smith&rsquo;s and Rainey&rsquo;s improvised lyrics when Davis began her research.</p>"},{"id":"ced48b1d-8290-4dd8-89a8-675b567732ee","content":"<p>According to Davis, the songs sung by Rainey were more musically innovative than those sung by Smith typically were.</p>"}],"keys":["766432a0-203e-4196-a836-8b2ed7ce85c4"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it describes the songs sung by Gertrude \"Ma\" Rainey and Bessie Smith in a way the text implies is accurate. The text describes Angela Y. Davis&rsquo;s research on Rainey and Smith for her book <em>Blues Legacies and Black Feminism</em>, focusing on her efforts to transcribe the improvised lyrics in Rainey&rsquo;s and Smith&rsquo;s songs. The text calls Davis&rsquo;s transcription process \"labor intensive\" since the lack of clarity in the recordings required her to listen to each repeatedly to verify the accuracy of her transcripts. The fact that Davis undertook a painstaking transcription process using only fairly low-fidelity recordings suggests that reliable transcriptions were otherwise unavailable to her.</p><p>Choice A is incorrect. The text doesn&rsquo;t discuss the popularity of Rainey&rsquo;s and Smith&rsquo;s songs either in the 1920s or after. Although it is plausible that the music of Rainey and Smith is more widely enjoyed than it was in the 1920s, this isn&rsquo;t supported by the text. Choice B is incorrect. The text doesn&rsquo;t discuss which of Rainey and Smith was the more prolific recording artist and so provides no support for such a claim. Choice D is incorrect. The text discusses the creativity of both Rainey and Smith, but it does so only to note similarities between them in terms of improvisation and wit, not to emphasize differences between them or Davis&rsquo;s relative views of the artists&rsquo; inventiveness.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323040,"updateDate":1730147323040}$SATQ$::jsonb, 1730147323040, 1730147323040),
    ($SATQ$f71802d6$SATQ$, $SATQ$30f294ab-b2a2-4e6f-bfc7-f099c4e68738$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<figure class="image"><svg xmlns="http://www.w3.org/2000/svg" width="400" height="567.2171630859375" viewBox="0 0 400 567.2171630859375" role="img" aria-label="Bar graph titled Percentage of Nonhexagonal Cells in Hives of Three Honeybee Species. The horizontal axis is labeled Species. 3 data categories are shown. The vertical axis is labeled Average percentage of nonhexagonal cells by shape. It ranges from 0 to 3.0 in increments of 0.5. Refer to long description."><g id="ed420550-79eb-48d4-af01-cd27cdd08afd" data-name="Layer 1"><defs>
